#dim tSC as %Status = $$$OK

try {

	set ..IsConnected = 0
	set ..ResetClientFlag = 0

	set ..ConnectionRetryEndTime = ##class(%SYSTEM.SQL).DATEADD("s",..ConnectionRetryTimeout,$ZTimestamp)

	set ..Client = ##class(OPCUA.Client).%New()
	set tSC = ..Client.Initialize()
	Quit:$$$ISERR(tSC)

	do ..ApplyLogFile()
	set tSC = ..Client.SetupClient("",..SecurityMode,..ClientURI,..PublicCertificate,..PrivateKey,..TrustListDir,..RevocationListDir)
	Quit:$$$ISERR(tSC)

} catch (e) {
	Set tSC=e.AsStatus()
}

if $$$ISERR(tSC) {
	$$$LOGERROR("OPCUA Client initialization failed [c.oi] : "_$SYSTEM.Status.GetErrorText(tSC))
	Quit tSC
} 

Quit tSC  // Quit $$$OK

set tSC = ..Client.SetLogFile(..LogFileTag)
if $$$ISERR(tSC) {
	$$$LOGWARNING("Could not set the OPC UA library log file '"_..LogFileTag_"': "_$System.Status.GetErrorText(tSC))
}

set tConnected = 0, pResetFlag = 0
Try {
	set tSC = pClient.GetClientState("", .tConnected, "", "", .tReset)
	if $$$ISERR(tSC) {
		set tConnected = 0
	} else {
		set pResetFlag = +$Get(tReset)
	}
} Catch (e) {
	set tConnected = 0
}
Quit +tConnected

#dim tSC as %Status = $$$OK

try {

	if ..ResetClientFlag '= 0 {

		do ..ApplyLogFile()
		set tSC = ..Client.SetupClient("",..SecurityMode,..ClientURI,..PublicCertificate,..PrivateKey,..TrustListDir,..RevocationListDir)

		if $$$ISERR(tSC) {

			$$$LOGERROR("Error encountered while resetting client [c.c] : "_$SYSTEM.Status.GetErrorText(tSC))
			Quit

		} else {

			$$$LOGINFO("OPCUA Client reset [c.c]")
		}
	}

	// Username and password come from the Credentials setting, an
	// Ens.Config.Credentials ID, never from plain-text settings. Ens resolves
	// the ID case-insensitively, and unset or "none" gives an empty entry: an
	// anonymous session. An ID that names no entry leaves no object, and is an
	// error rather than a silent anonymous connect. Setting Credentials again
	// reloads the entry, so a password changed in the Portal applies at the
	// next connect.
	set tUser = "", tPassword = ""
	if ..Credentials '= "" {
		set ..Credentials = ..Credentials
		if '$IsObject(..%CredentialsObj) {
			set tSC = $$$ERROR($$$GeneralError, "Credentials entry '"_..Credentials_"' does not exist")
			Quit
		}
		set tUser = ..%CredentialsObj.Username, tPassword = ..%CredentialsObj.Password
	}
	set tSC = ..Client.Connect(..URL, tUser, tPassword)
	//Quit:$$$ISERR(tSC)

} catch (e) {
	set tSC = e.AsStatus()
}

Quit tSC

#dim tSC as %Status = $$$OK
set pSpec = ""
set pMasks = ""
set pPaths = ""

try {
	if ..DataSourceClass = "" {
		set tSC = $$$ERROR($$$GeneralError, "DataSourceClass is not configured")
		Quit
	}

	if ..DeviceNodePaths = "" {
		set tSC = $$$ERROR($$$GeneralError, "DeviceNodePaths is empty — list at least one OPC UA device root, e.g. ns=2;s=Plant.AC1")
		Quit
	}

	set tSC = ##class(OPCUA.DataSource.Resolver).ParseDeviceNodePaths(..DeviceNodePaths, .tDevices, .tParseErrors)
	for i=1:1:$LL($Get(tParseErrors)) {
		$$$LOGWARNING("Ignoring unusable DeviceNodePaths entry — "_$LI(tParseErrors, i))
	}
	Quit:$$$ISERR(tSC)

	set tSC = ##class(OPCUA.DataSource.Resolver).ResolveSpecification(..Client, ..DataSourceClass, tDevices, .pSpec, .pMasks, .tDiagnostics)
	Quit:$$$ISERR(tSC)

	// Report every unresolved column, naming the device and the column.
	//
	// A partially matching device is a legitimate binding, not an error: the
	// coverage dry run (POST /schemas/:name/validate) shows exactly which
	// columns are missing before deploy, so a device bound anyway was bound
	// deliberately. Its unresolved columns store NULL and say so here.
	for i=1:1:$LL(tDiagnostics) {
		set tD = $LI(tDiagnostics, i)
		$$$LOGWARNING("Device '"_$LI(tD, 1)_"': column '"_$LI(tD, 2)_"' did not resolve — "_$LI(tD, 3)_". It will be stored as NULL.")
	}

	// NodePath values, in device order, for the service to tag rows with.
	for i=1:1:$LL(tDevices) {
		set pPaths = pPaths _ $LB($LI($LI(tDevices, i), 4))
	}

	set tTotal = 0
	for i=1:1:$LL(pMasks) {
		set tMask = $LI(pMasks, i)
		for c=1:1:$LL(tMask) {
			if +$LI(tMask, c) set tTotal = tTotal + 1
		}
	}
	$$$LOGINFO("Resolved "_..DataSourceClass_" against "_$LL(tDevices)_" device(s): "_tTotal_" node(s) to read")

} catch (e) {
	set tSC = e.AsStatus()
}

Quit tSC

#dim tSC as %Status = $$$OK

try {

	set tSC = ..Client.Disconnect()
	//Quit:$$$ISERR(tSC)

} catch (e) {
	set tSC = e.AsStatus()
}

Quit tSC

#dim tSC as %Status = $$$OK

try {

	set tSC = ..Client.Disconnect()

} catch (e) {
	Set tSC=e.AsStatus()
}

Quit tSC

#dim tSC as %Status = $$$OK

try {

	set ..Specification = pSpecification

} catch (e) {
	set tSC = e.AsStatus()
}

Quit tSC

Quit:..DeviceNodePaths="" ##super()

#dim tSC as %Status = $$$OK
try {
	set tSC = ..ResolveRowSourceSpec(.tSpec, .tMasks, .tPaths)
	Quit:$$$ISERR(tSC)

	set ..Specification = tSpec
	set ..RowSourceMasks = tMasks
	set ..RowSourcePaths = tPaths
} catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

#dim tSC as %Status = $$$OK

try {

	if ..QueryHandle > 0 {

		set tSC = ..Client.ReadBulkClear(..QueryHandle)
		// do not quit on clear failure

		set ..QueryHandle = 0
	}

	set tSC = ##super()
	Quit:$$$ISERR(tSC)

	// Row-source adapters resolve their Specification here, against the live
	// session. Default implementation is a no-op.
	set tSC = ..ResolveSpecification()
	Quit:$$$ISERR(tSC)

	#dim tmp as %Integer
	set tSC = ..Client.ReadBulkSetupC(.tmp,..Specification)
	Quit:$$$ISERR(tSC)

	set ..QueryHandle = tmp

} catch (e) {
	Set tSC=e.AsStatus()
}

// A live session with no query is not a usable connection.
//
// OnTask only re-Connects while IsConnected is false, and IsConnected is
// derived from the OPC UA session state — which stays perfectly healthy when
// it is *resolution* that failed. Leaving the session up would therefore let
// every later poll run against QueryHandle 0, whose "handle = 0" error then
// masks the real cause forever. Dropping the session makes the next OnTask
// retry Connect, and so retry resolution — which is also what lets a device
// that only becomes browsable later start reporting on its own.
if $$$ISERR(tSC) && (..QueryHandle '> 0) {
	// Status ignored: the setup error in tSC is the one to report.
	do ..Disconnect()
	set ..IsConnected = 0
}

Quit tSC  // Quit $$$OK

#dim tSC as %Status = $$$OK

#dim tQtyProcessed as %Integer = 0
#dim tStartTime as %TimeStamp = $ZTimestamp

try {

	if '..IsConnected {

		set tSC = ..Connect()
		$$$ThrowOnError(tSC)

		$$$LOGINFO("OPCUA adapter connected to "_..URL)			
	}

	#dim tList as %List

	set tSC = ..Client.ReadBulkPollC(.tList,..QueryHandle)
	Quit:$$$ISERR(tSC)

	set tSC = ..BusinessHost.ProcessInput(.tList)  
	Quit:$$$ISERR(tSC)

} catch (e) {
	Set tSC = e.AsStatus()
}

set tEndTime = $ZTimestamp
set tElapsedTime = ##class(%SYSTEM.SQL).DATEDIFF("ms",tStartTime,tEndTime) / 1000.0 // in seconds

if $$$ISERR(tSC) {

	set ..IsConnected = ..ConnectedState(..Client)

	if ..LastReportedError '= tSC {

		if ##class(OPCUA.Utils).AreSimilarOpcuaDisconnectErrors($SYSTEM.Status.GetErrorText(..LastReportedError),$SYSTEM.Status.GetErrorText(tSC)) {

			$$$TRACE("Error encountered : "_$SYSTEM.Status.GetErrorText(tSC)_" : "_..Client.GetClientStateString())

		} else {

			$$$LOGERROR("Error encountered : "_$SYSTEM.Status.GetErrorText(tSC)_" : "_..Client.GetClientStateString())
		}

		set ..LastReportedError = tSC
		set ..BusinessHost.%WaitForNextCallInterval = 1	

	} else {
		$$$TRACE("Error encountered : "_$SYSTEM.Status.GetErrorText(tSC)_" : "_..Client.GetClientStateString())
	}

	$$$SetHostMonitor(..BusinessHost.%ConfigName,$$$eMonitorStatus,"Error")

	if ##class(%SYSTEM.SQL).DATEDIFF("s",..ConnectionRetryEndTime,$ZTimestamp) > 0 {
		if ..AlwaysConnect {
			$$$LOGWARNING("Client has not been able to establish the connection within the last "_..ConnectionRetryTimeout_" seconds")
			set ..ConnectionRetryEndTime = ##class(%SYSTEM.SQL).DATEADD("s",..ConnectionRetryTimeout,$ZTimestamp)
		} else {
			$$$LOGERROR("Connection retry period concluded. Unable to establish connection.")
			set ..BusinessHost.%QuitTask = 1
		}
		return tSC
	}

} else {

	set ..IsConnected = 1

	set ..LastReportedError = tSC // $$$OK
	set ..BusinessHost.%WaitForNextCallInterval = 1

	$$$TRACE("1 record entered in "_tElapsedTime_" seconds. : "_..Client.GetClientStateString())

	$$$SetHostMonitor(..BusinessHost.%ConfigName,$$$eMonitorStatus,"OK")

	set ..ConnectionRetryEndTime = ##class(%SYSTEM.SQL).DATEADD("s",..ConnectionRetryTimeout,$ZTimestamp)

} 

Quit $$$OK

try {
	do ..Client.ReadBulkClear(..QueryHandle)	// Perhaps unnecessary
} catch (e) {
	// Best-effort teardown: the session is closing anyway, and ##super() must still run.
}

return ##super()

#dim tSC as %Status = $$$OK

try {

	set ..Specification = pSpecification

} catch (e) {
	set tSC = e.AsStatus()
}

Quit tSC

Quit:..DeviceNodePaths="" ##super()

#dim tSC as %Status = $$$OK
try {
	set tSC = ..ResolveRowSourceSpec(.tSpec, .tMasks, .tPaths)
	Quit:$$$ISERR(tSC)

	set ..Specification = tSpec
	set ..RowSourceMasks = tMasks
	set ..RowSourcePaths = tPaths
} catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

#dim tSC as %Status = $$$OK

try {

	set tSC = ##super()
	Quit:$$$ISERR(tSC)

	$$$TRACE("OPCUA subscription adapter connected to "_..URL)

} catch (e) {
	Set tSC=e.AsStatus()
}

if $$$ISERR(tSC) {
	$$$TRACE("OPCUA subscription adapter unable to connect to "_..URL_" : "_$SYSTEM.Status.GetErrorText(tSC))
	Quit tSC
} 

try {

	// Row-source adapters resolve their Specification here, against the live
	// session established above (browsing needs one). Default is a no-op, so
	// the declarative v1 path is unaffected.
	set tSC = ..ResolveSpecification()
	Quit:$$$ISERR(tSC)

	#dim tHandle as %Integer
	#dim tPublishingInterval as %Double = ..RequestedPublishingInterval
	#dim tLifetimeCount as %Integer = ..RequestedLifetimeCount
	#dim tMaxKeepAliveCount as %Integer = ..RequestedMaxKeepAliveCount
	#dim tSamplingInterval as %Integer = ..RequestedSamplingInterval
	#dim tQueueSize as %Integer = ..RequestedQueueSize
	#dim tMaxInternalQueueSize as %Integer = ..MaxInternalQueueSize

	set tSC = ..Client.CreateSubscriptionSetB(.tHandle,..Specification,.tPublishingInterval,.tLifetimeCount,.tMaxKeepAliveCount,..MaxNotificationsPerPublish,.tSamplingInterval,.tQueueSize,tMaxInternalQueueSize)
	Quit:$$$ISERR(tSC)

	set ..QueryHandle = tHandle

	$$$LOGINFO("OPCUA subscription created: Handle="_..QueryHandle_", PublishingInterval="_tPublishingInterval_", LifetimeCount="_tLifetimeCount_", MaxKeepAliveCount="_tMaxKeepAliveCount_", MaxSamplingInterval="_tSamplingInterval_", MinQueueSize="_tQueueSize)

} catch (e) {
	Set tSC=e.AsStatus()
}

if $$$ISERR(tSC) {

	$$$LOGERROR("OPCUA subscription query setup failed : "_$SYSTEM.Status.GetErrorText(tSC))

	// Status ignored: the setup error in tSC is the one to report.
	do ..Disconnect()

	Quit tSC
} 

Quit tSC  // Quit $$$OK

#dim tSC as %Status = $$$OK

#dim tQtyProcessed as %Integer = 0
#dim tProcessingErrors as %Integer = 0
#dim tFirstProcessingError as %Status = $$$OK

#dim tStartTime as %TimeStamp = $ZTimestamp

try {

	if (..IsConnected < 1) || (..ResetClientFlag '= 0) {

		set tSC = ..Connect()
		$$$ThrowOnError(tSC)

		set ..ResetClientFlag = 0
		set ..IsConnected = 1
		$$$LOGINFO("OPCUA adapter connected to "_..URL)			
	}

	#dim tList as %List

	set tSC = ..Client.PollSubscriptionSet(.tList,..QueryHandle,..SubscriptionPollingTimeout,..MaxBatchSize,1)
	Quit:$$$ISERR(tSC)

	//set tSC = ..BusinessHost.ProcessInput(.tList)  

	// *********

	set tQty = $LI(tList,2)
	set tBatch = $LI(tList,3)
	set tQueueStats = $LI(tList,4)

	set tQtyLost = $LI(tQueueStats,7) - $LI(tQueueStats,3) // Qty lost after - before
	set tQueueSizeLimit = $LI(tQueueStats,1) // zero if unlimited

	if tQtyLost > 0 {
		$$$LOGERROR("Data loss ("_tQtyLost_" elements). Internal queue size insufficient for incoming data rate.")
	} elseif tQueueSizeLimit > 0 {
		set tQueueUsage = $LI(tQueueStats,4) / tQueueSizeLimit // Queue size before processing / Max allowed size
		if tQueueUsage > 0.5 {
			$$$LOGWARNING("Internal queue utilized at greater than 50% capacity: "_tQueueUsage)
		}
	}

	if (..MaxBatchSize '= 0) && (tQty >= ..MaxBatchSize) {
		set tCurrentQueueSize = $LI(tQueueStats,6)
		set tQueueItemsProcessed = $LI(tQueueStats,4) - tCurrentQueueSize // Queue size before - after processing
		$$$LOGWARNING("Batch size capacity warning. Performance may degrade. Current queue items processed = "_tQueueItemsProcessed_". Current internal queue size = "_tCurrentQueueSize_".")
	}

	do ..ProcessBatch(tBatch, tQty, .tQtyProcessed, .tProcessingErrors, .tFirstProcessingError)

	// *********

	// Again, ensure that %WaitForNextCallInterval remains set.
	set ..BusinessHost.%WaitForNextCallInterval = 1

} catch (e) {
	Set tSC = e.AsStatus()
}

set tEndTime = $ZTimestamp
set tElapsedTime = ##class(%SYSTEM.SQL).DATEDIFF("ms",tStartTime,tEndTime) / 1000.0 // in seconds

if $$$ISERR(tSC) {

	set ..IsConnected = ..ConnectedState(..Client, .tTmpReset)
	set ..ResetClientFlag = tTmpReset

	if ..LastReportedError '= tSC {

		if ##class(OPCUA.Utils).ErrTextIsTypeInfo($SYSTEM.Status.GetErrorText(tSC)) {

			//$$$LOGINFO($SYSTEM.Status.GetErrorText(tSC))
			$$$TRACE($SYSTEM.Status.GetErrorText(tSC))
			set ..BusinessHost.%WaitForNextCallInterval = 0

		} elseif ##class(OPCUA.Utils).AreSimilarOpcuaDisconnectErrors($SYSTEM.Status.GetErrorText(..LastReportedError),$SYSTEM.Status.GetErrorText(tSC)) {

			$$$TRACE("Error encountered : "_$SYSTEM.Status.GetErrorText(tSC)_" : "_..Client.GetClientStateString())
			set ..BusinessHost.%WaitForNextCallInterval = 1	

		} else {

			$$$LOGERROR("Error encountered : "_$SYSTEM.Status.GetErrorText(tSC)_" : "_..Client.GetClientStateString())
			set ..BusinessHost.%WaitForNextCallInterval = 1	
		}
		set ..LastReportedError = tSC

	} else {
		$$$TRACE("Error encountered : "_$SYSTEM.Status.GetErrorText(tSC)_" : "_..Client.GetClientStateString())
	}

	$$$SetHostMonitor(..BusinessHost.%ConfigName,$$$eMonitorStatus,"Error")

	if (##class(%SYSTEM.SQL).DATEDIFF("ms",..ConnectionRetryEndTime,$ZTimestamp) > 0) {
		if ..AlwaysConnect {
			$$$LOGWARNING("Client has not been able to establish the connection within the last "_..ConnectionRetryTimeout_" seconds")
			set ..ConnectionRetryEndTime = ##class(%SYSTEM.SQL).DATEADD("s",..ConnectionRetryTimeout,$ZTimestamp)
		} else {
			$$$LOGERROR("Error encountered : Maximum time since a successful response exceeded : "_$SYSTEM.Status.GetErrorText(tSC))
			if ..IsConnected {
				set ..IsConnected = 0
			}
			set ..BusinessHost.%QuitTask = 1
		}
		return tSC
	}

} else {

	set ..IsConnected = 1

	set ..LastReportedError = tSC // $$$OK
	set ..BusinessHost.%WaitForNextCallInterval = 1

	if tProcessingErrors > 0 {

		$$$LOGWARNING(tProcessingErrors_" processing error(s) encountered concurrent with the successful entry of "_tQtyProcessed_" record(s). First error : "_$SYSTEM.Status.GetErrorText(tFirstProcessingError)_" : "_..Client.GetClientStateString())

		set ..QtySequentialEmptyResults = 0

	} elseif tQtyProcessed > 0 {

		//$$$TRACE("1 record entered in "_tElapsedTime_" seconds.")
		$$$TRACE(tQtyProcessed_" record(s) entered in "_tElapsedTime_" seconds with no errors encountered : "_..Client.GetClientStateString())	

		set ..QtySequentialEmptyResults = 0

	} else {

		// No results were returned. Is the client connected?
		set ..IsConnected = ..ConnectedState(..Client)

		if ..IsConnected = 0 {

			$$$LOGWARNING("Connection lost : "_..Client.GetClientStateString())

		} elseif ..ReestablishOnEmptyResult > 0 {

			$$$TRACE(tQtyProcessed_" record(s) entered in "_tElapsedTime_" seconds with no errors encountered : "_..Client.GetClientStateString())	

			// Connection may have been dropped and should perhaps be reestablished 
			set ..QtySequentialEmptyResults = ..QtySequentialEmptyResults + 1

			if ..QtySequentialEmptyResults >= ..ReestablishOnEmptyResult {

				$$$LOGWARNING("Maximum number of sequential empty results exceeded. Disconnecting.")

				// Disconnecting deletes the subscription: the session is closed with
				// deleteSubscriptions = true, so no DeleteSubscriptionSet is needed.
				try {
					set tSC = ..Client.Disconnect()
				} catch (e) {
					set tSC = e.AsStatus()
				}

				if $$$ISERR(tSC) {
					$$$TRACE("Ignoring error encountered when disconnecting : "_$SYSTEM.Status.GetErrorText(tSC))
				}

				set ..IsConnected = 0
				set ..ResetClientFlag = 1
				set ..QtySequentialEmptyResults = 0
			}

		} else {

			$$$TRACE(tQtyProcessed_" record(s) entered in "_tElapsedTime_" seconds with no errors encountered : "_..Client.GetClientStateString())	
		}

	}

	$$$SetHostMonitor(..BusinessHost.%ConfigName,$$$eMonitorStatus,"OK")

	set ..ConnectionRetryEndTime = ##class(%SYSTEM.SQL).DATEADD("s",..ConnectionRetryTimeout,$ZTimestamp)
} 

Quit $$$OK

set pQtyProcessed = 0, pErrors = 0, pFirstError = $$$OK

for i=1:1:pQty {

	// Ensure that this is set even in the event of error.
	// (If an error occurs within ProcessInput(), then
	// %WaitForNextCallInterval should hopefully still be set.)
	set ..BusinessHost.%WaitForNextCallInterval = 1

	try {
		set tItemSC = ..BusinessHost.ProcessInput($LI(pBatch,i))
	} catch (e) {
		set tItemSC = e.AsStatus()
	}

	if $$$ISERR(tItemSC) {

		$$$TRACE("Error encountered processing adapter output, continuing... : "_$SYSTEM.Status.GetErrorText(tItemSC))
		set pErrors = pErrors + 1
		set:pErrors=1 pFirstError = tItemSC

	} else {

		set pQtyProcessed = pQtyProcessed + 1
	}
}

// $ListGet: an error list without a message (or code) must still decode. $List
// would throw, and the caller would report <NULL VALUE> instead of the error.
Set tType=$ListGet(list,2),tCode=$ListGet(list,3),tMsgTxt=$ListGet(list,4)
Set:tMsgTxt="" tMsgTxt="OPC UA library error, type "_tType_", code "_tCode
If tType=$$$ErrorTypeNone {
	Set tTypeTxt=$$$Text("No Error")
} elseif tType=$$$ErrorTypeInfo {
	Set tTypeTxt=$$$Text("Incomplete w/o Err")
} elseif tType=$$$ErrorTypeApp {
	Set tTypeTxt=$$$Text("Application Error")
} elseif tType=$$$ErrorTypeCallin {
	Set tTypeTxt=$$$Text("Callin Error")
} elseif tType=$$$ErrorTypeOPCUA {
	Set tTypeTxt=$$$Text("OPC Error")
} elseif tType=$$$ErrorTypeClient {
	Set tTypeTxt=$$$Text("Client Error")
} elseif tType=$$$ErrorTypeServer {
	Set tTypeTxt=$$$Text("Server Error")
} elseif tType=$$$ErrorTypeUnknown {
	Set tTypeTxt="Unknown Error"
} else {
	Set tTypeTxt=$$$Text("Undefined Error")
}

// $$$GeneralError (5001), not a private code: 29000 is an IRIS system error
// ("Context class '%1' does not exist") and would replace this message
Quit $$$ERROR($$$GeneralError,tMsgTxt)

