#dim tSC As %Status = $$$OK
#dim e As %Exception.AbstractException

Try {
	write "OPCUA DataSource Generator", !
	write "==========================", !

	// Initialize library
	set tSC = ##class(OPCUA.Utils).Initialize()
	Quit:$$$ISERR(tSC)

	// Create and setup client
	write "Connecting to "_URL_"...", !
	set tClient = ##class(OPCUA.Client).%New()
	set tSC = tClient.Initialize()
	Quit:$$$ISERR(tSC)

	set tSC = tClient.SetupClient(, SecurityMode)
	Quit:$$$ISERR(tSC)

	set tSC = tClient.Connect(URL, Username, Password)
	Quit:$$$ISERR(tSC)
	write "Connected.", !

	// Browse recursively from the start node
	write "Browsing from node (ns="_StartNodeNS_", id="_StartNodeId_")...", !
	set tNodeCount = 0
	do ..BrowseRecursive(tClient, StartNodeNS, StartNodeId, StartNodeIdType, 0, MaxDepth, .tNodes, .tNodeCount, .tVisited)

	write "Found "_tNodeCount_" variable node(s).", !

	if tNodeCount > 0 {
		// Determine default namespace from discovered nodes
		set tDefaultNS = ..DetermineDefaultNamespace(.tNodes, tNodeCount, StartNodeNS)

		// Generate the class file
		set tSC = ..GenerateClassFile(ClassName, DataSourceName, tDefaultNS, OutputPath, .tNodes, tNodeCount)
		Quit:$$$ISERR(tSC)
	} else {
		write "No variable nodes found. No file generated.", !
	}

	// Disconnect. Status ignored: the file is already written, and a failed
	// disconnect of a terminal tool's session changes nothing for the user.
	write "Disconnecting...", !
	do tClient.Disconnect()
	write "Done.", !

} Catch (e) {
	Set tSC = e.AsStatus()
	// Try to disconnect on error
	Try {
		if $IsObject($Get(tClient)) do tClient.Disconnect()
	} Catch (e2) {
		// Best-effort cleanup: the original error in tSC must win.
	}
}

Quit tSC

// Check max depth
if pDepth >= pMaxDepth {
	write $Justify("", (pDepth+1)*2)_"[max depth reached]", !
	Quit
}

// Check for cycles
set tKey = pNodeNS_":"_pNodeIdType_":"_pNodeId
if $Data(pVisited(tKey)) Quit
set pVisited(tKey) = 1

Try {
	// Browse this node's children
	set tSC = pClient.Browse(.tResults, $LB(pNodeIdType), $LB(pNodeNS), $LB(pNodeId))
	if $$$ISERR(tSC) {
		write $Justify("", (pDepth+1)*2)_"Warning: Browse failed for node (ns="_pNodeNS_", id="_pNodeId_")", !
		Quit
	}

	// Extract reference list from browse results
	// Each reference: [1]=refType, [2]=isForward, [3]=nodeInfo, [4]=browseName,
	//                 [5]=displayName, [6]=nodeClass(empty), [7]=typeDef
	set tBrowseData = $LI(tResults, 4)
	set tFirstResult = $LI(tBrowseData, 1)
	set tRefList = $LI(tFirstResult, 4)
	set tRefCount = $LL(tRefList)

	if tRefCount = 0 Quit

	// Process each child reference
	for i=1:1:tRefCount {
		set tRef = $LI(tRefList, i)

		// Check reference type - skip HasTypeDefinition (ns=0, id=40)
		set tRefTypeInfo = $LI(tRef, 1)
		set tRefTypeNS = $LI(tRefTypeInfo, 1)
		set tRefTypeId = $LI(tRefTypeInfo, 2)
		if (tRefTypeNS = 0) && (tRefTypeId = 40) continue

		set tNodeInfo = $LI(tRef, 3)
		set tDisplayInfo = $LI(tRef, 4)

		set tChildNS = $LI(tNodeInfo, 1)
		set tChildId = $LI(tNodeInfo, 2)
		set tChildIdType = $LI(tNodeInfo, 3)
		set tChildName = $LI(tDisplayInfo, 1)

		// Skip empty display names
		if tChildName = "" set tChildName = "Node"_tChildId

		set tIndent = $Justify("", (pDepth+1)*2)

		// Classify using type definition from browse metadata [7]
		set tClass = ..ClassifyByTypeDef($LI(tRef, 7))

		if tClass = "Variable" {
			do ..ProcessVariableNode(pClient, tChildNS, tChildId, tChildIdType, tChildName, .pNodes, .pNodeCount)
			set tInferred = $LI(pNodes(pNodeCount), 5)
			set tShortType = $Piece(tInferred, ".", *)
			write tIndent_"+ "_tChildName_" (ns="_tChildNS_", id="_tChildId_") ["_tShortType_"]", !
		} elseif tClass = "Object" {
			write tIndent_"> "_tChildName_"/", !
			// Recurse into folder/object
			do ..BrowseRecursive(pClient, tChildNS, tChildId, tChildIdType, pDepth + 1, pMaxDepth, .pNodes, .pNodeCount, .pVisited)
		}
		// "Unknown" nodes are silently skipped
	}

} Catch (e) {
	write $Justify("", (pDepth+1)*2)_"Warning: Error processing node (ns="_pNodeNS_", id="_pNodeId_"): "_e.DisplayString(), !
}

Quit

set tResult = "Unknown"
Try {
	set tTypeDefNS = $LI(pTypeDef, 1)
	set tTypeDefId = $LI(pTypeDef, 2)

	// Empty or null type definition
	if (tTypeDefNS = "") || (tTypeDefId = "") || (tTypeDefId = 0) {
		Quit
	}

	// Well-known OPC UA variable types in namespace 0
	if tTypeDefNS = 0 {
		if (tTypeDefId = 62) || (tTypeDefId = 63) || (tTypeDefId = 68) {
			set tResult = "Variable"
		} else {
			// Everything else in ns=0 is an Object type (FolderType, ServerType, etc.)
			set tResult = "Object"
		}
		Quit
	}

	// Custom type in non-standard namespace: default to Variable
	// (user reviews and adjusts the generated file)
	set tResult = "Variable"
} Catch (e) {
	// Malformed type definition
}
Quit tResult

set tType = ""
// A bulk specification identifies a node by a bare string, and the native
// layer treats one made of digits as a numeric id. A string id that is all
// digits, a GUID or a ByteString therefore cannot be asked about this way.
set tProbeable = (pNodeIdType = $$$OpcuaNodeIdTypeNumeric) || ((pNodeIdType = $$$OpcuaNodeIdTypeString) && '$Match(pNodeId, "^\d+$"))
if tProbeable && ..ReadTypeAttributes(pClient, pNodeNS, pNodeId, .tDataType, .tValueRank) {
	// ValueRank: -1 scalar, 1 array, >1 matrix, 0 one or more dimensions;
	// -2 (Any) and -3 (ScalarOrOneDimension) leave it to the value.
	set tDims = $Select(tValueRank >= 0:$Select(tValueRank = 0:1, 1:tValueRank), tValueRank = -1:0, 1:..ValueDimensions(pClient, pNodeNS, pNodeId))
	set tType = ..MapDataTypeToIRIS(tDataType, tDims)
}
Quit $Select(tType '= "":tType, 1:..InferTypeFromValue(pClient, pNodeNS, pNodeId, pNodeIdType))

set (pDataType, pValueRank) = ""
Quit:'..ReadAttributesOnce(pClient, pNodeNS, pNodeId, $LB($$$OpcuaAttributeDataType, $$$OpcuaAttributeValueRank), .tResults) 0
// A missing attribute is "", and a failed read a DataValue with no value;
// the length and ValueRank checks below reject both. DataType arrives as a
// NodeId inlined into its DataValue:
// $LB(sourceTS, serverTS, status, namespace, identifier, identifierType, ...)
set tDT = $ListGet(tResults, 1)
set tVR = $ListGet(tResults, 2)
Quit:'$ListValid(tDT)||($ListLength(tDT) < 5)||'$ListValid(tVR)||($ListLength(tVR) < 4) 0
set pDataType = $Select($ListGet(tDT, 4) = 0:$ListGet(tDT, 5), 1:"")
set pValueRank = $ListGet(tVR, 4)
Quit (pValueRank '= "")

set pResults = ""
set tEntries = $LB("")
for i=1:1:$ListLength(pAttributes) {
	set tEntries = tEntries _ $LB($LB(2, "[TypeProbe].A"_$List(pAttributes, i), pNodeNS, pNodeId, $List(pAttributes, i)))
}
set tSpec = $LB("TypeProbe", "", tEntries)
set tHandle = ""
set tOK = 0
Try {
	Quit:$$$ISERR(pClient.ReadBulkSetupC(.tHandle, .tSpec))
	Quit:$$$ISERR(pClient.ReadBulkPollC(.tPoll, tHandle))
	// $LB(errCode, result1, result2, ...)
	set pResults = $List(tPoll, 2, *)
	set tOK = 1
} Catch (e) {
	set tOK = 0
}
if tHandle '= "" {
	// Best-effort cleanup of a one-shot probe: its result is already decided.
	Try { do pClient.ReadBulkClear(tHandle) } Catch (eClear) {}
}
Quit tOK

// A few standard subtypes that servers commonly declare instead of their base:
// Duration, UtcTime, IntegerId, Counter, VersionTime, Enumeration (an Int32
// on the wire), LocaleId, and the Normalized/Decimal/Duration/Time/DateString
// string types.
set tBase = pTypeNodeId
if pTypeNodeId = 290 { set tBase = 11 }
elseif pTypeNodeId = 294 { set tBase = 13 }
elseif (pTypeNodeId = 288) || (pTypeNodeId = 289) || (pTypeNodeId = 20998) { set tBase = 7 }
elseif pTypeNodeId = 29 { set tBase = 6 }
elseif (pTypeNodeId = 295) || ((pTypeNodeId >= 12877) && (pTypeNodeId <= 12881)) { set tBase = 12 }

// Scalar class, and the array class where one exists.
if tBase = 1 { set tScalar = "BooleanDataValue", tArray = "Boolean" }
elseif (tBase >= 2) && (tBase <= 9) { set tScalar = "IntegerDataValue", tArray = "Integer" }
elseif tBase = 10 { set tScalar = "FloatDataValue", tArray = "Float" }
elseif tBase = 11 { set tScalar = "DoubleDataValue", tArray = "Double" }
elseif tBase = 12 { set tScalar = "StringDataValue", tArray = "String" }
elseif tBase = 13 { set tScalar = "TimeStampDataValue", tArray = "TimeStamp" }
elseif tBase = 16 { set tScalar = "StringDataValue", tArray = "String" }    // XmlElement
elseif tBase = 19 { set tScalar = "IntegerDataValue", tArray = "Integer" }  // StatusCode
elseif tBase = 17 { set tScalar = "NodeIdDataValue", tArray = "" }
elseif tBase = 20 { set tScalar = "QualifiedNameDataValue", tArray = "" }
elseif tBase = 21 { set tScalar = "LocalizedTextDataValue", tArray = "" }
else { Quit "" }

if pDimensions = 0 Quit "OPCUA.Types."_tScalar
// A matrix, or an array of a type with no typed array class, is kept as the
// generic list-of-lists.
if (pDimensions > 1) || (tArray = "") Quit "OPCUA.Types.Multidimensional"
Quit "OPCUA.Types.ArrayDataValue."_tArray

set tDefault = "OPCUA.Types.StringDataValue"
Try {
	// Read the value attribute (attribute 13 - the only one the C++ layer supports)
	set tSC = pClient.ReadValueAttribute(.tResults, pNodeId, pNodeNS, pNodeIdType)
	if $$$ISERR(tSC) Quit

	// Result format: $LB(errCode, sourceTS, serverTS, status, value)
	if $ListLength(tResults) < 5 Quit
	if $LI(tResults, 1) '= 0 Quit

	set tValue = $LI(tResults, 5)

	// Null or empty value — can't infer
	if tValue = "" Quit

	// Check if the value is a $List (array type)
	if $ListValid(tValue) {
		// Array — peek at first element to determine element type
		if $ListLength(tValue) = 0 Quit
		set tFirst = $LI(tValue, 1)
		if tFirst = "" Quit
		if (tFirst = 1) || (tFirst = 0) {
			// Could be boolean array, but also integer 0/1 — prefer integer
			Quit  // fall through to default
		}
		if $Match(tFirst, "^-?\d+$") {
			set tDefault = "OPCUA.Types.ArrayDataValue.Integer"
			Quit
		}
		if $Match(tFirst, "^-?\d*\.\d+([eE][+-]?\d+)?$") || $Match(tFirst, "^-?\d+[eE][+-]?\d+$") {
			set tDefault = "OPCUA.Types.ArrayDataValue.Double"
			Quit
		}
		set tDefault = "OPCUA.Types.ArrayDataValue.String"
		Quit
	}

	// Scalar type inference
	// Boolean: exactly "true"/"false" or 0/1 from OPC UA booleans
	// Note: C++ layer converts booleans to 0/1, same as small integers.
	// We can't distinguish boolean from integer by value alone,
	// so we only match if the value is clearly non-numeric for string,
	// or numeric for integer/double.

	// Timestamp pattern: "YYYY-MM-DD HH:MM:SS[.fraction]" (ODBC format from C++ layer)
	// $Match requires full string match, so use .* to allow trailing fractional seconds
	if $Match(tValue, "^\d{4}-\d{2}-\d{2}\s\d{2}:\d{2}:\d{2}.*") {
		set tDefault = "OPCUA.Types.TimeStampDataValue"
		Quit
	}

	// Pure integer (possibly negative)
	if $Match(tValue, "^-?\d+$") {
		// Known limitation: Double/Float values of 0.0 are canonicalized to "0"
		// by ObjectScript string conversion, making them indistinguishable from
		// integer 0 here. Non-zero doubles (e.g. 3.14) are correctly detected
		// below. Proper fix requires reading the OPC UA DataType attribute.
		set tDefault = "OPCUA.Types.IntegerDataValue"
		Quit
	}

	// Floating point (with decimal point or scientific notation)
	if $Match(tValue, "^-?\d*\.\d+([eE][+-]?\d+)?$") || $Match(tValue, "^-?\d+[eE][+-]?\d+$") || ($IsValidDouble(tValue) && (tValue '= +tValue)) {
		set tDefault = "OPCUA.Types.DoubleDataValue"
		Quit
	}

	// Everything else is a string
	set tDefault = "OPCUA.Types.StringDataValue"

} Catch (e) {
	// Read failed — use default
}
Quit tDefault

set tClean = ""
set tPrevUnderscore = 0
for i=1:1:$Length(pName) {
	set tChar = $Extract(pName, i)
	if (tChar ? 1A) || (tChar ? 1N) || (tChar = "_") {
		set tClean = tClean _ tChar
		set tPrevUnderscore = (tChar = "_")
	} else {
		// Replace with underscore, avoiding consecutive underscores
		if 'tPrevUnderscore && (tClean '= "") {
			set tClean = tClean _ "_"
			set tPrevUnderscore = 1
		}
	}
}

// Remove trailing underscores
while ($Length(tClean) > 0) && ($Extract(tClean, *) = "_") {
	set tClean = $Extract(tClean, 1, *-1)
}

// Ensure doesn't start with a digit
if ($Length(tClean) > 0) && ($Extract(tClean, 1) ? 1N) {
	set tClean = "N" _ tClean
}

// Fallback if empty
if tClean = "" set tClean = "Node"

// Truncate to reasonable length
if $Length(tClean) > 96 set tClean = $Extract(tClean, 1, 96)

// Deduplicate by appending counter suffix
set tBase = tClean
set tCounter = 1
while $Data(pUsedNames(tClean)) {
	set tCounter = tCounter + 1
	set tClean = tBase _ tCounter
}
set pUsedNames(tClean) = 1

Quit tClean

if pNodeCount = 0 Quit pFallback

// Count namespace frequency
for i=1:1:pNodeCount {
	set tNS = $LI(pNodes(i), 1)
	if '$Data(tNSCount(tNS)) {
		set tNSCount(tNS) = 1
	} else {
		set tNSCount(tNS) = tNSCount(tNS) + 1
	}
}

// Find most common namespace
set tMaxCount = 0
set tMaxNS = pFallback
set tNS = ""
for {
	set tNS = $Order(tNSCount(tNS))
	if tNS = "" Quit
	if tNSCount(tNS) > tMaxCount {
		set tMaxCount = tNSCount(tNS)
		set tMaxNS = tNS
	}
}

Quit tMaxNS

#dim tSC As %Status = $$$OK
#dim e As %Exception.AbstractException

Try {
	// Build file path: "Generated.PLCDataSource" -> "Generated/PLCDataSource.cls"
	set tFileName = $Translate(pClassName, ".", "/") _ ".cls"
	set tOutputDir = pOutputPath
	if $Extract(tOutputDir, *) '= "/" {
		set tOutputDir = tOutputDir _ "/"
	}
	set tFilePath = tOutputDir _ tFileName

	// Create directory chain if needed
	set tDir = ##class(%File).GetDirectory(tFilePath)
	if '##class(%File).DirectoryExists(tDir) {
		if '##class(%File).CreateDirectoryChain(tDir) {
			set tSC = $$$ERROR($$$GeneralError, "Failed to create directory: "_tDir)
			Quit
		}
	}

	// Open file stream for writing
	set tStream = ##class(%Stream.FileCharacter).%New()
	set tSC = tStream.LinkToFile(tFilePath)
	Quit:$$$ISERR(tSC)

	// Write class header
	do tStream.WriteLine("/// Auto-generated DataSource definition from OPC UA server browse.")
	do tStream.WriteLine("/// Review property types and adjust as needed (default: StringDataValue).")
	do tStream.WriteLine("Class "_pClassName_" Extends (%Persistent, OPCUA.DataSource.Definition)")
	do tStream.WriteLine("{")
	do tStream.WriteLine("")
	do tStream.WriteLine("Parameter OPCUADATASOURCE = """_pDataSourceName_""";")
	do tStream.WriteLine("")
	do tStream.WriteLine("Parameter OPCUDEFAULTANAMESPACE = "_pDefaultNS_";")

	// Write properties
	for i=1:1:pNodeCount {
		set tNodeInfo = pNodes(i)
		set tNodeNS = $LI(tNodeInfo, 1)
		set tNodeId = $LI(tNodeInfo, 2)
		set tNodeIdType = $LI(tNodeInfo, 3)
		set tDisplayName = $LI(tNodeInfo, 4)

		// Sanitize display name for property name
		set tPropName = ..SanitizePropertyName(tDisplayName, .tUsedNames)

		// Use inferred type from position 5, fall back to StringDataValue
		set tType = $LI(tNodeInfo, 5)
		if tType = "" set tType = "OPCUA.Types.StringDataValue"

		// Build property parameter list
		set tParams = "OPCUANODENAME = """_tNodeId_""""

		// Add explicit namespace if different from default
		if tNodeNS '= pDefaultNS {
			set tParams = tParams _ ", OPCUANAMESPACE = """_tNodeNS_""""
		}

		do tStream.WriteLine("")
		do tStream.WriteLine("Property "_tPropName_" As "_tType_"("_tParams_");")
	}

	do tStream.WriteLine("")
	do tStream.WriteLine("}")
	do tStream.WriteLine("")

	// Save the file
	set tSC = tStream.%Save()
	Quit:$$$ISERR(tSC)

	write "Generated: "_tFilePath, !
	write pNodeCount_" properties written.", !

} Catch (e) {
	Set tSC = e.AsStatus()
}

Quit tSC

#Dim oClassDef As %Dictionary.CompiledClass

Set tSC = $$$OK
Try 
{
    // We don't do nothing when the abstract base classes are compiled —
    // they declare no properties and carry no OPCUADATASOURCE parameter.
    Quit:cls="OPCUA.DataSource.Definition"
    Quit:cls="OPCUA.DataSource.DeviceSchema"

    Set oClassDef = ##class(%Dictionary.CompiledClass).%OpenId(cls)

    Set tDataSourceName = ..GetParameterValue(oClassDef, "OPCUADATASOURCE")

    If tDataSourceName=""
    {
        Set tSC = $$$ERROR(5001, "OPCUADATASOURCE parameter is not defined in "_cls)
        Quit
    }

    Set tOPCUADefaultNamespace = ..GetParameterValue(oClassDef, "OPCUDEFAULTANAMESPACE")        

    Set tSC = ..ProcessObj(oClassDef, tOPCUADefaultNamespace, "", "["_tDataSourceName_"]", .lConfigSpec)
    Quit:$$$ISERR(tSC)

    Set tStorageGlobal = oClassDef.Storages.GetAt(1).DataLocation

    Do ..CommitOPCUAConfigSpec(tDataSourceName, cls, tStorageGlobal, lConfigSpec)

}
Catch (oException)
{
    Set tSC = oException.AsStatus()
}

Quit tSC

Set tSC = $$$OK
Set lConfigSpec=""

Set oStorageDataEntries = oObj.Storages.GetAt(1).Data.GetAt(1).Values

// We must respect the storage entries order. We can't rely on the order of properties on the class definition.
For i=1:1:oStorageDataEntries.Count()
{
    Set tPropName = oStorageDataEntries.GetAt(i).Value
    Continue:$Extract(tPropName,1)="%"
    Continue:tPropName="NodePath"
    Continue:tPropName="ServerTimeStamp"
    Continue:tPropName="SourceTimeStamp"

    // But we still need the property definition for each storage entry...
    Set bPropFound=0
    For iProp=1:1:oObj.Properties.Count()
    {
        Set oProp=oObj.Properties.GetAt(iProp)
        If oProp.Name=tPropName 
        {
            Set bPropFound=1
            Quit
        }
    }    

    // Someone may have deleted the property from the class definition and left the old storage definition. 
    // That is ok!!!! So we must tell the OPCUA C layer to "put nothing" in there.
    If 'bPropFound
    {
        Set lConfigSpec=lConfigSpec_$LB("")
        Continue
    }

    // Now I have the right propert definition for the storage entry

    Set tOPCUANamespace = oProp.Parameters.GetAt("OPCUANAMESPACE")
    If tOPCUANamespace="" Set tOPCUANamespace=pOPCUADefaultNamespace

    If tOPCUANamespace=""
    {
        // oObj, not cls: cls only exists in CreateProjection. The parameter really
        // is spelled OPCUDEFAULTANAMESPACE (see OPCUA.DataSource.Definition).
        Set tSC = $$$ERROR(5001, "OPCUANAMESPACE parameter is not defined for property "_oProp.Name_" from class "_oObj.Name_" and there is no OPCUDEFAULTANAMESPACE parameter defined in class "_oObj.Name)
        Quit
    }

    if '$System.Version.IsUnicode() {
        set tSC = ##class(OPCUA.Utils).Initialize() // required for GetUStr on 8-bit IRIS
        Quit:$$$ISERR(tSC) // if initialization fails, report the error (GetUStr will not)
    }
    Set tNodeName = ""
    Set tNodeNameRaw = oProp.Parameters.GetAt("OPCUANODENAME")
    Set tNodeName = ##class(OPCUA.Utils).GetUStr(tNodeNameRaw)
    //Write !,"tNodeName for property ",pPropertyPath_"."_tPropName,": ",tNodeName

    // Are we overwriting the previous node name? If after overwriting, we end up with a empty node name, we will be validating it later
    // There are more opportunities to define the node name. This may be a CustomStructure
    If tNodeName="" Set tNodeName=pDefaultNodeName

    // Same here. We will be validating if we have a node attribute ID later
    Set tNodeAttributeId = oProp.Parameters.GetAt("OPCUAATTRIBUTEID")
    if tNodeAttributeId="" Set tNodeAttributeId=13 // Value Attribute

    // We have three types of properties: 
    // - Primitive values (code 1)
    // - Standard OPCUA structures (code 2)
    // - Custom structures (just a list)

    // Primitive values are identified when the user defines a simple data type on his/her class
    If $classmethod(oProp.Type, "%Extends", "%DataType")
    {
        // Using code 1 on the first parameter to say this is just a primitive 
        Set tSC = ..CreateConfigSpecEntry(1, pPropertyPath_"."_oProp.Name, tOPCUANamespace, tNodeName, tNodeAttributeId, .lConfigSpecEntry)
        Quit:$$$ISERR(tSC)
    }
    // A custom structure must inherit from OPCUA.Structure.CustomStructure
    ElseIf $classmethod(oProp.Type, "%Extends", "OPCUA.Structure.CustomStructure") 
    {
        Set oPropTypeClass = ##class(%Dictionary.CompiledClass).%OpenId(oProp.Type)
        Set tSC = ..ProcessObj(oPropTypeClass, tOPCUANamespace, tNodeName, pPropertyPath_"."_oProp.Name, .lConfigSpecEntry)
        Quit:$$$ISERR(tSC)
    }
    // A standard OPCUA structure belongs to the package OPCUA.Structure (or OPCUA.Types)
    ElseIf $Extract(oProp.Type,1,16)="OPCUA.Structure."
    {
        // Using code 2 on the first parameter to say this is a standard OPCUA structure
        Set tSC = ..CreateConfigSpecEntry(2, pPropertyPath_"."_oProp.Name, tOPCUANamespace, tNodeName, tNodeAttributeId, .lConfigSpecEntry)
        Quit:$$$ISERR(tSC)
    }
    // A measurement, with or without its server timestamp. Both are read as
    // the full DataValue; RowWriter drops the server timestamp where needed.
    ElseIf ($Extract(oProp.Type,1,12)="OPCUA.Types.") || $classmethod(oProp.Type, "%Extends", "OPCUA.Types.AbstractDataValue") || $classmethod(oProp.Type, "%Extends", "OPCUA.Types.NoServerTS.AbstractDataValue")
    {
        // Using code 2 on the first parameter to say this is a standard OPCUA structure
        Set tSC = ..CreateConfigSpecEntry(2, pPropertyPath_"."_oProp.Name, tOPCUANamespace, tNodeName, tNodeAttributeId, .lConfigSpecEntry)
        Quit:$$$ISERR(tSC)
    }
    ElseIf $classmethod(oProp.Type, "%Extends", "%SerialObject")
    {
        // Pipeline-generated serial object for nested OPC UA sub-folders.
        // Recurse into the serial class to process its properties.
        Set oPropTypeClass = ##class(%Dictionary.CompiledClass).%OpenId(oProp.Type)
        Set tSC = ..ProcessObj(oPropTypeClass, tOPCUANamespace, tNodeName, pPropertyPath_"."_oProp.Name, .lConfigSpecEntry)
        Quit:$$$ISERR(tSC)
        // Append the serial object's entries directly — the recursive call already
        // returns a $LB of entries. Don't wrap again via the $LB() at end of loop.
        Set lConfigSpec = lConfigSpec _ lConfigSpecEntry
        Continue
    }
    Else
    {
        Set tSC = $$$ERROR(5001, "Property "_oProp.Name_" has an invalid type for OPCUA: "_oProp.Type)
        Quit
    }

    Set lConfigSpec=lConfigSpec_$LB(lConfigSpecEntry)

} //For

Quit tSC

Set tSC = $$$OK
Set pConfigSpecEntry=""

Try 
{
    If pNodeName=""
    {
        Set tSC = $$$ERROR(5001, "Property "_pPropertyPath_" does not specify an OPCUANODENAME.")
        Quit
    }

    If pNodeAttributeId=""
    {
        Set tSC = $$$ERROR(5001, "Property "_pPropertyPath_" does not specify an OPCUAATTRIBUTEID.")
        Quit
    }

    Set pConfigSpecEntry=$LB(pEntryType, pPropertyPath, pOPCUANamespace, pNodeName, pNodeAttributeId)
} 
Catch (oException)
{
    Set tSC = oException.AsStatus()
}

Quit tSC

// Specifications are supplied in the form of %List
// 1. DataSource name
// 2. The name of the global on which to save the results
// 3. A multidimensional %List of property elements.
//		1. The first element is perhaps usually null (or the name of the class if a subclass?)
//		2. Property elements take the form of a list with elements:
//			1. The type of element: 1 = Primitives, 2 = Standard OPCUA, 3 = ?
//			2. The pPropertyPath_"."_oProp.Name e.g. "[MyDataSource2].Temperature"
//			3. The namespace
//			4. The node name, a string NodeId identifier
//			5. The AttributeId

return ^OPCUA.DataSource(pClassName)

#Dim oParam As %Dictionary.CompiledParameter

For i=1:1:pClassDef.Parameters.Count()
{
    Set oParam = pClassDef.Parameters.GetAt(i)
    If oParam.Name=pParameterName 
    {
        Return oParam.Default
    }
}

Return ""

Set tSC = $$$OK
Try
{
    Kill ^OPCUA.DataSource(cls)
} 
Catch (oException)
{
    Set tSC = oException.AsStatus()
}

QUIT tSC

#dim tSC As %Status = $$$OK
set pDevices = ""
set pErrors = ""
Try {
	// Normalise CRLF / CR line endings to LF, then split.
	set tText = $Replace(pSetting, $Char(13, 10), $Char(10))
	set tText = $Replace(tText, $Char(13), $Char(10))

	for iLine=1:1:$Length(tText, $Char(10)) {
		set tLine = $ZStrip($Piece(tText, $Char(10), iLine), "<>W")
		continue:tLine=""
		continue:$Extract(tLine)="#"

		// Optional "|label" suffix
		set tLabel = ""
		if tLine [ "|" {
			set tLabel = $ZStrip($Piece(tLine, "|", 2, *), "<>W")
			set tLine = $ZStrip($Piece(tLine, "|", 1), "<>W")
		}
		if tLabel = "" set tLabel = tLine

		set tSCLine = ..ParseNodePath(tLine, .tNS, .tId, .tIdType)
		if $$$ISERR(tSCLine) {
			set pErrors = pErrors _ $LB("Line "_iLine_" ("_tLine_"): "_$System.Status.GetOneErrorText(tSCLine))
			continue
		}

		set pDevices = pDevices _ $LB($LB(tNS, tId, tIdType, tLabel))
	}

	if $LL(pDevices) = 0 {
		set tSC = $$$ERROR($$$GeneralError, "DeviceNodePaths did not yield any usable device entries")
	}
} Catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

set pNS = 0
set pId = ""
set pIdType = $$$OpcuaNodeIdTypeString

// Surrounding whitespace is not part of the nodepath. The webapp's
// parseNodeId() trims first too, and the two must agree.
set tPath = $ZStrip(pPath, "<>W")
set tRest = tPath

// Leading "ns=<n>;"
if $ZConvert($Extract(tRest, 1, 3), "L") = "ns=" {
	set tNSPart = $Piece(tRest, ";", 1)
	set tNSVal = $Extract(tNSPart, 4, *)
	if tNSVal '? 1.N {
		Quit $$$ERROR($$$GeneralError, "namespace must be numeric in 'ns=<n>;...'")
	}
	set pNS = +tNSVal
	set tRest = $Piece(tRest, ";", 2, *)
}

if tRest = "" {
	Quit $$$ERROR($$$GeneralError, "missing node identifier — expected 's=<name>' or 'i=<number>'")
}

set tKind = $ZConvert($Extract(tRest, 1, 2), "L")
set tVal = $Extract(tRest, 3, *)

if tKind = "s=" {
	if tVal = "" Quit $$$ERROR($$$GeneralError, "empty string identifier in 's='")
	set pId = tVal
	set pIdType = $$$OpcuaNodeIdTypeString
	Quit $$$OK
}

if tKind = "i=" {
	if tVal '? 1.N Quit $$$ERROR($$$GeneralError, "numeric identifier expected in 'i='")
	set pId = +tVal
	set pIdType = $$$OpcuaNodeIdTypeNumeric
	Quit $$$OK
}

if tKind = "g=" {
	if tVal = "" Quit $$$ERROR($$$GeneralError, "empty GUID identifier in 'g='")
	set pId = tVal
	set pIdType = $$$OpcuaNodeIdTypeGUID
	Quit $$$OK
}

if tKind = "b=" {
	if tVal = "" Quit $$$ERROR($$$GeneralError, "empty ByteString identifier in 'b='")
	set pId = tVal
	set pIdType = $$$OpcuaNodeIdTypeByteString
	Quit $$$OK
}

// Browse-path form (e.g. /Plant/AC1) is not supported yet — see PRD Q1,
// which ships the NodeId form first.
if $Extract(tPath) = "/" {
	Quit $$$ERROR($$$GeneralError, "browse-path form is not supported yet — use ns=<n>;s=<name> or ns=<n>;i=<number>")
}

Quit $$$ERROR($$$GeneralError, "unrecognised nodepath — expected ns=<n>;s=<name> or ns=<n>;i=<number>")

#dim tSC As %Status = $$$OK
kill pColumns, pFolders
set pColumns = 0
Try {
	set tSpec = $Get(^OPCUA.DataSource(pSchemaClass))
	if tSpec = "" {
		set tSC = $$$ERROR($$$GeneralError, "No compiled OPC UA spec found for "_pSchemaClass_" — is the class compiled?")
		Quit
	}

	set tColumnSpec = $LI(tSpec, 3)

	// Map each property path prefix that is a %SerialObject folder to the
	// folder's OPC UA node name, so nested columns know their parent.
	set tSC = ..MapSerialFolders(pSchemaClass, .tFolderMap)
	Quit:$$$ISERR(tSC)

	// Position 1 of the column spec is the class marker; columns start at 2.
	for i=2:1:$LL(tColumnSpec) {
		set tEntry = $LI(tColumnSpec, i)
		continue:tEntry=""

		set tPropPath = $LI(tEntry, 2)
		set tNamespace = $LI(tEntry, 3)
		set tNodeName = $LI(tEntry, 4)
		set tAttrId = $LI(tEntry, 5)

		// A nested column's property path is "[DS].Folder.Leaf" — one segment
		// deeper than a flat column's "[DS].Leaf".
		set tFolderName = ""
		if $Length(tPropPath, ".") > 2 {
			set tParentPath = $Piece(tPropPath, ".", 1, $Length(tPropPath, ".") - 1)
			set tFolderName = $Get(tFolderMap(tParentPath))
		}

		set pColumns = pColumns + 1
		set pColumns(pColumns) = $LB(tPropPath, tNamespace, tNodeName, tAttrId, tFolderName)
		set:tFolderName'="" pFolders(tFolderName) = ""
	}

	if pColumns = 0 {
		set tSC = $$$ERROR($$$GeneralError, "Schema "_pSchemaClass_" declares no OPC UA columns")
	}
} Catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

#dim tSC As %Status = $$$OK
kill pFolderMap
Try {
	set tClassDef = ##class(%Dictionary.CompiledClass).%OpenId(pSchemaClass)
	if '$IsObject(tClassDef) {
		set tSC = $$$ERROR($$$GeneralError, "Cannot open compiled class: "_pSchemaClass)
		Quit
	}

	set tDSName = ""
	for i=1:1:tClassDef.Parameters.Count() {
		set tParam = tClassDef.Parameters.GetAt(i)
		if tParam.Name = "OPCUADATASOURCE" set tDSName = tParam.Default
	}

	for i=1:1:tClassDef.Properties.Count() {
		set tProp = tClassDef.Properties.GetAt(i)
		set tType = tProp.Type
		continue:$Extract(tType,1)="%"
		continue:..IsMeasurementType(tType)
		continue:$Extract(tType,1,16)="OPCUA.Structure."

		Try {
			if $classmethod(tType, "%Extends", "%SerialObject") {
				set tNodeName = tProp.Parameters.GetAt("OPCUANODENAME")
				if tNodeName = "" set tNodeName = tProp.Name
				// Property path as the Projection builds it: "[DSName].PropName"
				set pFolderMap("["_tDSName_"]."_tProp.Name) = tNodeName
			}
		} Catch (eInner) {
			// Type class may not exist — not a folder we can descend into.
		}
	}
} Catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

#dim tSC As %Status = $$$OK
set pNestingSpec = ""
set pLeafTypes = ""
Try {
	set tClassDef = ##class(%Dictionary.CompiledClass).%OpenId(pSchemaClass)
	if '$IsObject(tClassDef) {
		set tSC = $$$ERROR($$$GeneralError, "Cannot open compiled class: "_pSchemaClass)
		Quit
	}

	// Index the class's properties by name so storage entries can be typed.
	kill tPropType, tPropNode
	for i=1:1:tClassDef.Properties.Count() {
		set tProp = tClassDef.Properties.GetAt(i)
		set tPropType(tProp.Name) = tProp.Type
		set tNodeName = tProp.Parameters.GetAt("OPCUANODENAME")
		set tPropNode(tProp.Name) = $Select(tNodeName="":tProp.Name, 1:tNodeName)
	}

	set tEntries = tClassDef.Storages.GetAt(1).Data.GetAt(1).Values
	set tLeafIdx = 0
	set tHasNesting = 0

	for i=1:1:tEntries.Count() {
		set tName = tEntries.GetAt(i).Value
		continue:$Extract(tName,1)="%"
		continue:tName="NodePath"
		continue:tName="ServerTimeStamp"
		continue:tName="SourceTimeStamp"

		set tType = $Get(tPropType(tName))
		set tIsSerial = 0
		if (tType '= "") && ($Extract(tType,1)'="%") && '..IsMeasurementType(tType) {
			Try {
				set tIsSerial = $classmethod(tType, "%Extends", "%SerialObject")
			} Catch (eInner) {
				set tIsSerial = 0
			}
		}

		if 'tIsSerial {
			set tLeafIdx = tLeafIdx + 1
			set pNestingSpec = pNestingSpec _ $LB($LB("leaf", tLeafIdx))
			set pLeafTypes = pLeafTypes _ $LB(tType)
			continue
		}

		// A nested folder: one inner leaf per property of the serial class,
		// in the serial class's own storage order.
		set tHasNesting = 1
		set tInnerSpec = ""
		set tSerialDef = ##class(%Dictionary.CompiledClass).%OpenId(tType)
		if $IsObject(tSerialDef) {
			kill tInnerType
			for j=1:1:tSerialDef.Properties.Count() {
				set tInnerType(tSerialDef.Properties.GetAt(j).Name) = tSerialDef.Properties.GetAt(j).Type
			}
			set tSerialEntries = tSerialDef.Storages.GetAt(1).Data.GetAt(1).Values
			for j=1:1:tSerialEntries.Count() {
				set tInnerName = tSerialEntries.GetAt(j).Value
				continue:$Extract(tInnerName,1)="%"
				set tLeafIdx = tLeafIdx + 1
				set tInnerSpec = tInnerSpec _ $LB($LB("leaf", tLeafIdx))
				set pLeafTypes = pLeafTypes _ $LB($Get(tInnerType(tInnerName)))
			}
		}
		set pNestingSpec = pNestingSpec _ $LB($LB("serial", $Get(tPropNode(tName), tName), tInnerSpec))
	}

	// A flat schema needs no nesting spec at all — the services treat "" as flat.
	if 'tHasNesting set pNestingSpec = ""

} Catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

set tIs = 0
Try {
	set tIs = $classmethod(pType, "%Extends", "OPCUA.Types.AbstractDataValue") || $classmethod(pType, "%Extends", "OPCUA.Types.NoServerTS.AbstractDataValue")
} Catch (e) {
	set tIs = 0
}
Quit tIs

set tIs = 0
Try {
	set tIs = $classmethod(pType, "%Extends", "OPCUA.Types.NoServerTS.AbstractDataValue")
} Catch (e) {
	set tIs = 0
}
Quit tIs

#dim tSC As %Status = $$$OK
set pSpec = ""
set pMasks = ""
set pDiagnostics = ""
set pBrowseOK = ""
Try {
	if '$IsObject($Get(pClient)) {
		set tSC = $$$ERROR($$$GeneralError, "ResolveSpecification requires a connected OPCUA.Client")
		Quit
	}

	set tSC = ..GetSchemaColumns(pSchemaClass, .tColumns, .tFolders)
	Quit:$$$ISERR(tSC)

	set tBaseSpec = $Get(^OPCUA.DataSource(pSchemaClass))
	set tDSName = $LI(tBaseSpec, 1)
	set tStorageGlobal = $LI(tBaseSpec, 2)

	set tEntries = $LB("")

	for iDev=1:1:$LL(pDevices) {
		set tDev = $LI(pDevices, iDev)
		set tDevNS = $LI(tDev, 1)
		set tDevId = $LI(tDev, 2)
		set tDevIdType = $LI(tDev, 3)
		set tDevLabel = $LI(tDev, 4)

		// --- Browse the device root, and each folder one level deeper ---
		kill tNameMap
		set tSCBrowse = ..BrowseIntoMap(pClient, tDevNS, tDevId, tDevIdType, .tNameMap)
		if $$$ISERR(tSCBrowse) {
			// A device that cannot be browsed contributes an all-zero mask:
			// its columns store NULL rather than failing the whole pipeline.
			set pDiagnostics = pDiagnostics _ $LB($LB(tDevLabel, "*", "device root could not be browsed: "_$System.Status.GetOneErrorText(tSCBrowse)))
		}

		// Whether the server answered the browse at all. Zero matches means
		// something quite different depending on this: a browsed device with no
		// matches is the wrong node, an unbrowsable one is simply unreachable.
		// Callers that gate on coverage need to tell those apart.
		set pBrowseOK = pBrowseOK _ $LB($$$ISOK(tSCBrowse))

		// Descend into each %SerialObject folder the schema declares.
		set tFolder = ""
		for {
			set tFolder = $Order(tFolders(tFolder))
			quit:tFolder=""
			set tFolderRef = $Get(tNameMap(..NameKey(tFolder)))
			if tFolderRef = "" {
				set pDiagnostics = pDiagnostics _ $LB($LB(tDevLabel, tFolder, "folder not found on device"))
				continue
			}
			kill tSubMap
			set tSCSub = ..BrowseIntoMap(pClient, $LI(tFolderRef, 1), $LI(tFolderRef, 2), $LI(tFolderRef, 3), .tSubMap)
			if $$$ISERR(tSCSub) {
				set pDiagnostics = pDiagnostics _ $LB($LB(tDevLabel, tFolder, "folder could not be browsed: "_$System.Status.GetOneErrorText(tSCSub)))
				continue
			}
			// Store folder children under a folder-qualified key.
			set tKey = ""
			for {
				set tKey = $Order(tSubMap(tKey))
				quit:tKey=""
				set tNameMap(..NameKey(tFolder), tKey) = tSubMap(tKey)
			}
		}

		// --- Match each schema column against the browsed names ---
		set tMask = ""
		for iCol=1:1:tColumns {
			set tCol = tColumns(iCol)
			set tNodeName = $LI(tCol, 3)
			set tAttrId = $LI(tCol, 4)
			set tFolderName = $LI(tCol, 5)

			if tFolderName = "" {
				set tRef = $Get(tNameMap(..NameKey(tNodeName)))
			} else {
				set tRef = $Get(tNameMap(..NameKey(tFolderName), ..NameKey(tNodeName)))
			}

			if tRef = "" {
				set tMask = tMask _ $LB(0)
				set tWhere = $Select(tFolderName="":tNodeName, 1:tFolderName_"/"_tNodeName)
				set pDiagnostics = pDiagnostics _ $LB($LB(tDevLabel, tWhere, "no child node matched this name"))
				continue
			}

			set tMask = tMask _ $LB(1)

			// Force type 2 so the C++ layer returns a full DataValue with
			// timestamps, matching what the row-source services expect.
			set tEntries = tEntries _ $LB($LB(
				2,
				$LI(tCol, 1)_"_RS"_iDev,
				$LI(tRef, 1),
				$LI(tRef, 2),
				tAttrId
			))
		}

		set pMasks = pMasks _ $LB(tMask)
	}

	set pSpec = $LB(tDSName, tStorageGlobal, tEntries)

} Catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

#dim tSC As %Status = $$$OK
kill pMap
Try {
	set tSC = pClient.Browse(.tResults, $LB(pIdType), $LB(pNS), $LB(pId))
	Quit:$$$ISERR(tSC)

	set tCount = ##class(OPCUA.REST.BrowseService).WalkBrowseResults(tResults, .tChildren)

	// Two passes so BrowseName always wins over a colliding DisplayName.
	for i=1:1:tCount {
		set tChild = tChildren(i)
		set tBrowseName = $LI(tChild, 1)
		continue:tBrowseName=""
		set tKey = ..NameKey(tBrowseName)
		if '$Data(pMap(tKey)) {
			set pMap(tKey) = $LB($LI(tChild, 3), $LI(tChild, 4), $LI(tChild, 5))
		}
	}
	for i=1:1:tCount {
		set tChild = tChildren(i)
		set tDisplayName = $LI(tChild, 2)
		continue:tDisplayName=""
		set tKey = ..NameKey(tDisplayName)
		if '$Data(pMap(tKey)) {
			set pMap(tKey) = $LB($LI(tChild, 3), $LI(tChild, 4), $LI(tChild, 5))
		}
	}
} Catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

#dim tSC As %Status = $$$OK

try {
	set tDSClass = pDSClass
	if tDSClass = "" {
		set tSC = $$$ERROR($$$GeneralError, "DataSourceClass is not configured")
		Quit
	}

	if '##class(%Dictionary.CompiledClass).%ExistsId(tDSClass) {
		set tSC = $$$ERROR($$$GeneralError, "Schema class '"_tDSClass_"' does not exist or is not compiled")
		Quit
	}

	// Read compiled class storage to determine actual $LB positions.
	// IRIS default storage orders properties alphabetically, so we must
	// discover the actual positions of NodePath, ServerTimeStamp,
	// SourceTimeStamp and each data column.
	set tSC = ..DiscoverStorageLayout(tDSClass)
	Quit:$$$ISERR(tSC)

	// Derive the nesting layout from the class rather than from stored
	// metadata, so it can never go stale relative to the compiled schema.
	set tSC = ##class(OPCUA.DataSource.Resolver).DeriveNestingSpec(tDSClass, .tNesting, .tLeafTypes)
	Quit:$$$ISERR(tSC)
	set ..NestingSpec = tNesting
	set ..OmitServerTS = ""
	for i=1:1:$LL(tLeafTypes) {
		set ..OmitServerTS = ..OmitServerTS _ $LB(##class(OPCUA.DataSource.Resolver).OmitsServerTimeStamp($ListGet(tLeafTypes, i)))
	}

	// Read the existing projection's leaf types rather than guessing from the
	// pipeline version. This also keeps already-deployed plain schemas working.
	set tSpec = ##class(OPCUA.DataSource.Projection).GetOPCUAConfigSpec(tDSClass)
	set tEntries = $LI(tSpec, 3)
	set ..FullDataValues = ""
	for i=2:1:$LL(tEntries) {
		set tEntry = $LI(tEntries, i)
		continue:tEntry=""
		set ..FullDataValues = ..FullDataValues _ $LB($LI(tEntry, 1) = 2)
	}

	set tSC = ##class(OPCUA.DataSource.Resolver).GetSchemaColumns(tDSClass, .tColumns)
	Quit:$$$ISERR(tSC)
	set ..ColumnLabels = ""
	for i=1:1:tColumns {
		set tFolder = $LI(tColumns(i), 5)
		set ..ColumnLabels = ..ColumnLabels _ $LB($Select(tFolder = "":"", 1:tFolder_"/")_$LI(tColumns(i), 3))
	}
	kill ..LastSeverity

} catch (e) {
	set tSC = e.AsStatus()
}

Quit tSC

#dim tSC As %Status = $$$OK
try {
	set oClassDef = ##class(%Dictionary.CompiledClass).%OpenId(pDSClass)
	if '$IsObject(oClassDef) {
		set tSC = $$$ERROR($$$GeneralError, "Cannot open compiled class: "_pDSClass)
		Quit
	}
	set oEntries = oClassDef.Storages.GetAt(1).Data.GetAt(1).Values
	set ..RowSize = oEntries.Count()
	set ..NodePathPos = 0, ..ServerTSPos = 0, ..SourceTSPos = 0
	set tDataPositions = ""
	for i=1:1:oEntries.Count() {
		set tPropName = oEntries.GetAt(i).Value
		set tPos = i
		if tPropName = "NodePath" { set ..NodePathPos = tPos }
		elseif tPropName = "ServerTimeStamp" { set ..ServerTSPos = tPos }
		elseif tPropName = "SourceTimeStamp" { set ..SourceTSPos = tPos }
		elseif $Extract(tPropName, 1) '= "%" {
			set tDataPositions = tDataPositions _ $LB(tPos)
		}
	}
	set ..DataColumnPositions = tDataPositions
} catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

set tExpected = 1
for iRS=1:1:$LL(pMasks) {
	set tMask = $LI(pMasks, iRS)
	for iCol=1:1:$LL(tMask) { set tExpected = tExpected + (+$LI(tMask, iCol)) }
}
set tGot = $Select($ListValid(pInput):$LL(pInput), 1:0)
if tGot '= tExpected {
	Quit $$$ERROR($$$GeneralError, "Got "_$Select(tGot > 0:tGot - 1, 1:0)_" readings for "_(tExpected - 1)_" resolved columns. They are matched by position, so nothing was stored for this cycle rather than store values under the wrong columns.")
}
Quit $$$OK

#dim tSC As %Status = $$$OK
set pRow = ""
set pQualityChanges = ""
try {
	if $LL(pMask) '= $LL(..FullDataValues) {
		set tSC = $$$ERROR($$$GeneralError, "Device mask does not match the compiled schema")
		Quit
	}
	set tColumnCount = $LL(pMask)
	set tServerTS = ""
	set tSourceTS = ""
	set tGotTimestamp = 0

	// Keep each leaf DataValue intact; legacy plain properties receive its value.
	// Unresolved columns consume no result entry — they are simply NULL.
	kill tLeafValues
	set tLeafIdx = 0
	for iCol=1:1:tColumnCount {
		set tLeafIdx = tLeafIdx + 1
		if '+$LI(pMask, iCol) {
			set tLeafValues(tLeafIdx) = ""
			continue
		}

		set pResultIndex = pResultIndex + 1
		// $ListGet: an empty slot stores NULL for this column. $List would throw
		// and lose this device and every device after it for the cycle.
		set tDV = $ListGet(pInput, pResultIndex)

		if $ListValid(tDV) && ($LL(tDV) >= 4) {
			if 'tGotTimestamp {
				set tSourceTS = $ListGet(tDV, 1)
				set tServerTS = $ListGet(tDV, 2)
				set tGotTimestamp = 1
			}
			// A DataValue is already serialized in OPCUA.Types storage order:
			// source timestamp, server timestamp, status, value (or array values).
			// A Bad reading has no value, so element 4 is null: $ListGet, not $List.
			set tLeafValues(tLeafIdx) = $Select($LI(..FullDataValues, iCol):tDV, 1:$ListGet(tDV, 4))
			// A NoServerTS measurement stores everything but element 2. The range
			// form keeps null elements (a Bad reading's value) and every payload
			// field after the status.
			if $LI(..FullDataValues, iCol) && $ListGet(..OmitServerTS, iCol) {
				set tLeafValues(tLeafIdx) = $List(tDV, 1, 1) _ $List(tDV, 3, *)
			}

			// Severity is the top two bits of the StatusCode; 3 is reserved and
			// counts as Bad.
			set tStatus = +$ListGet(tDV, 3)
			set tSeverity = $Select(tStatus \ 1073741824 >= 2:2, 1:tStatus \ 1073741824)
			set tLast = $Get(..LastSeverity(pPath, iCol))
			if (tLast '= tSeverity) && '((tLast = "") && (tSeverity = 0)) {
				set pQualityChanges = pQualityChanges _ $LB($LB(iCol, tLast, tSeverity, tStatus))
			}
			set ..LastSeverity(pPath, iCol) = tSeverity
		} else {
			if $LI(..FullDataValues, iCol) && (tDV '= "") {
				$$$ThrowStatus($$$ERROR($$$GeneralError, "Malformed DataValue for device '"_pPath_"', column "_iCol))
			}
			set tLeafValues(tLeafIdx) = tDV
		}
	}

	// Build the values portion of the row data
	set tValues = ""
	if ..NestingSpec = "" {
		// No nesting: flat $LB
		for v=1:1:tLeafIdx {
			set tValues = tValues _ $LB($Get(tLeafValues(v)))
		}
	} else {
		// Nesting: assemble nested $LB from the derived nesting spec
		set tValues = ..BuildNestedValues(..NestingSpec, .tLeafValues)
	}

	// Build row data matching the actual %Persistent storage layout.
	// Storage positions are alphabetical, so we place each value at
	// its compiled storage position rather than assuming a fixed order.
	set pRow = ""
	for p=1:1:..RowSize { set pRow = pRow _ $LB("") }
	set $LI(pRow, 1) = ""
	set $LI(pRow, ..NodePathPos) = pPath
	if ..ServerTSPos > 0 set $LI(pRow, ..ServerTSPos) = tServerTS
	if ..SourceTSPos > 0 set $LI(pRow, ..SourceTSPos) = tSourceTS
	for v=1:1:$LL(tValues) {
		if v <= $LL(..DataColumnPositions) {
			set $LI(pRow, $LI(..DataColumnPositions, v)) = $LI(tValues, v)
		}
	}
} catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

Quit:pQualityChanges=""
set tWorse = 0
kill tGroups
for i=1:1:$LL(pQualityChanges) {
	set tChange = $LI(pQualityChanges, i)
	set tOld = $LI(tChange, 2), tNew = $LI(tChange, 3), tStatus = $LI(tChange, 4)
	set:(tOld = "")||(tNew > tOld) tWorse = 1
	set tKey = tOld_"|"_tNew_"|"_tStatus
	set tGroups(tKey) = $Get(tGroups(tKey)) _ $LB($ListGet(..ColumnLabels, $LI(tChange, 1)))
}

set tNames = $LB("Good", "Uncertain", "Bad")
set tText = ""
set tKey = ""
for {
	set tKey = $Order(tGroups(tKey))
	quit:tKey=""
	set tOld = $Piece(tKey, "|", 1), tNew = $Piece(tKey, "|", 2), tStatus = $Piece(tKey, "|", 3)
	set tPart = $ListToString(tGroups(tKey), ", ")_": "
	set tPart = tPart _ $Select(tOld = "":"", 1:$LI(tNames, tOld + 1)_" -> ")_$LI(tNames, tNew + 1)
	// Name the status unless it is plain Good, which says nothing new.
	if tStatus '= 0 {
		set tName = ""
		// Name lookup is decoration: on failure tName stays "" and the code is shown.
		Try { do ##class(OPCUA.Client).GetStatusCodeName(.tName, tStatus) } Catch (e) {}
		set tPart = tPart _ " ("_$Select(tName '= "":tName, 1:"status "_tStatus)_")"
	}
	set tText = tText _ $Select(tText = "":"", 1:"; ") _ tPart
}

set tMsg = "Device '"_pPath_"': reading quality "_$Select(tWorse:"degraded", 1:"recovered")_" - "_tText
if tWorse {
	$$$LOGWARNING(tMsg)
} else {
	$$$LOGINFO(tMsg)
}

set tResult = ""
for i=1:1:$LL(pNestingSpec) {
	set tEntry = $LI(pNestingSpec, i)
	set tType = $LI(tEntry, 1)

	if tType = "leaf" {
		set tLeafIdx = $LI(tEntry, 2)
		set tResult = tResult _ $LB($Get(pLeafValues(tLeafIdx)))
	} elseif tType = "serial" {
		// Build inner $LB for the serial object
		set tInnerSpec = $LI(tEntry, 3)
		set tAllNull = 1
		for j=1:1:$LL(tInnerSpec) {
			set tInner = $LI(tInnerSpec, j)
			set tInnerLeafIdx = $LI(tInner, 2)
			if $Get(pLeafValues(tInnerLeafIdx)) '= "" {
				set tAllNull = 0
				quit
			}
		}
		if tAllNull {
			set tResult = tResult _ $LB("")
		} else {
			set tInnerLB = ""
			for j=1:1:$LL(tInnerSpec) {
				set tInner = $LI(tInnerSpec, j)
				set tInnerLeafIdx = $LI(tInner, 2)
				set tInnerLB = tInnerLB _ $LB($Get(pLeafValues(tInnerLeafIdx)))
			}
			set tResult = tResult _ $LB(tInnerLB)
		}
	}
}
quit tResult

	#dim tSC as %Status = $$$OK

	try {

		Set tRetval=$ZF(-5,%ZUtilsIrisOpcuaLibraryId,$$$zfDateConvOPCUA2HOROLOG,"",$LB(pOPCUA))

        If $List(tRetval,1)'=0 Set tSC=##class(OPCUA.Client).DecodeError(tRetval) Quit

		set pHOROLOG = $List(tRetval,2)

	} catch (e) {
		set tSC = e.AsStatus()
	}

	Quit tSC

	#dim tSC as %Status = $$$OK

	try {

		Set tRetval=$ZF(-5,%ZUtilsIrisOpcuaLibraryId,$$$zfDateConvHOROLOG2OPCUA,"",$LB(pHOROLOG))

        If $List(tRetval,1)'=0 Set tSC=##class(OPCUA.Client).DecodeError(tRetval) Quit

		set pOPCUA = $List(tRetval,2)

	} catch (e) {
		set tSC = e.AsStatus()
	}

	Quit tSC

	#dim tSC as %Status = $$$OK

	try {

		Set tRetval=$ZF(-5,%ZUtilsIrisOpcuaLibraryId,$$$zfDateConvOPCUA2ODBC,"",$LB(pOPCUA))

        If $List(tRetval,1)'=0 Set tSC=##class(OPCUA.Client).DecodeError(tRetval) Quit

		set pODBC = $List(tRetval,2)

	} catch (e) {
		set tSC = e.AsStatus()
	}

	Quit tSC

	#dim tSC as %Status = $$$OK

	try {

		Set tRetval=$ZF(-5,%ZUtilsIrisOpcuaLibraryId,$$$zfDateConvODBC2OPCUA,"",$LB(pODBC))

        If $List(tRetval,1)'=0 Set tSC=##class(OPCUA.Client).DecodeError(tRetval) Quit

		set pOPCUA = $List(tRetval,2)

	} catch (e) {
		set tSC = e.AsStatus()
	}

	Quit tSC

	#dim tSC as %Status = $$$OK

	try {

		Set tRetval=$ZF(-5,%ZUtilsIrisOpcuaLibraryId,$$$zfDateConvOPCUA2UNIX,"",$LB(pOPCUA))

        If $List(tRetval,1)'=0 Set tSC=##class(OPCUA.Client).DecodeError(tRetval) Quit

		set pUNIX = $List(tRetval,2)

	} catch (e) {
		set tSC = e.AsStatus()
	}

	Quit tSC

	#dim tSC as %Status = $$$OK

	try {

		Set tRetval=$ZF(-5,%ZUtilsIrisOpcuaLibraryId,$$$zfDateConvUNIX2OPCUA,"",$LB(pUNIX))

        If $List(tRetval,1)'=0 Set tSC=##class(OPCUA.Client).DecodeError(tRetval) Quit

		set pOPCUA = $List(tRetval,2)

	} catch (e) {
		set tSC = e.AsStatus()
	}

	Quit tSC

#dim tSC As %Status = $$$OK
#dim tClient As OPCUA.Client
Try {
	// Extract connection params
	set tSC = ##class(OPCUA.REST.ClientManager).ExtractConnectionParams(pBody, .tURL, .tSecMode, .tUser, .tPass, .tCert, .tKey, .tTrust, .tCrl, .tClientURI)
	Quit:$$$ISERR(tSC)

	// Node parameters with defaults (Root/Objects folder)
	set tNsVal = pBody.%Get("nodeNs")
	set tNodeNS = $Select(tNsVal="":0, 1:+tNsVal)
	set tIdVal = pBody.%Get("nodeId")
	set tNodeId = $Select(tIdVal="":84, 1:tIdVal)
	set tTypeVal = pBody.%Get("nodeIdType")
	set tNodeIdType = $Select(tTypeVal="":0, 1:+tTypeVal)

	// If nodeId looks numeric and type is not explicitly string, use numeric
	if (tNodeIdType = 0) && ($Match(tNodeId, "^\d+$")) {
		set tNodeId = +tNodeId
	} elseif tNodeIdType = 0 {
		set tNodeIdType = $$$OpcuaNodeIdTypeString
	}

	// Connect
	set tSC = ##class(OPCUA.REST.ClientManager).Connect(.tClient, tURL, tSecMode, tUser, tPass, tCert, tKey, tTrust, tCrl, tClientURI)
	Quit:$$$ISERR(tSC)

	// Browse
	set tSC = tClient.Browse(.tResults, $LB(tNodeIdType), $LB(tNodeNS), $LB(tNodeId))
	if $$$ISERR(tSC) Quit

	// Parse results into JSON array
	set pResult = ..ParseBrowseResults(tResults)

	// Turn the guessed expand arrows into measured ones, on the same connection.
	set tProbeVal = pBody.%Get("probeChildren")
	if (tProbeVal = "") || (+tProbeVal) {
		do ..ProbeChildCounts(tClient, pResult)
	}

} Catch (e) {
	set tSC = e.AsStatus()
}

do ##class(OPCUA.REST.ClientManager).Disconnect($Get(tClient))
Quit tSC

kill pChildren
set tCount = 0
Try {
	set tBrowseData = $LI(pResults, 4)
	set tFirstResult = $LI(tBrowseData, 1)
	set tRefList = $LI(tFirstResult, 4)

	for i=1:1:$LL(tRefList) {
		set tRef = $LI(tRefList, i)

		// --- Reference type (how child relates to parent) ---
		set tRefTypeInfo = $LI(tRef, 1)
		set tRefTypeNS = $LI(tRefTypeInfo, 1)
		set tRefTypeId = $LI(tRefTypeInfo, 2)

		if ..IsNonChildReference(tRefTypeNS, tRefTypeId) continue

		set tRefType = ..ClassifyReferenceType(tRefTypeNS, tRefTypeId)

		// --- Node identity ---
		set tNodeInfo = $LI(tRef, 3)
		set tChildNS = $LI(tNodeInfo, 1)
		set tChildId = $LI(tNodeInfo, 2)
		set tChildIdType = $LI(tNodeInfo, 3)

		// Elements 4-7 may be absent or empty (older library builds), so
		// they are read with $ListGet, never $LI.

		// --- BrowseName [4]: the stable, non-localized identifier ---
		set tBrowseInfo = $ListGet(tRef, 4)
		set tBrowseName = $Select($ListValid(tBrowseInfo):$ListGet(tBrowseInfo, 1), 1:"")

		// --- DisplayName [5]: localized presentation text ---
		set tDisplayInfo = $ListGet(tRef, 5)
		set tDisplayName = $Select($ListValid(tDisplayInfo):$ListGet(tDisplayInfo, 1), 1:"")

		// --- NodeClass [6]: the server's own answer, when the library gives it ---
		// Older prebuilt binaries predate the UA2CL_ReferenceDescription export of
		// this field and leave it empty; ClassifyNode falls back to inference then.
		set tNodeClass = $ListGet(tRef, 6)

		// --- Type definition (what kind of Object/Variable) ---
		set tTypeDefInfo = $ListGet(tRef, 7)
		set tTypeDefNS = $Select($ListValid(tTypeDefInfo):$ListGet(tTypeDefInfo, 1), 1:"")
		set tTypeDefId = $Select($ListValid(tTypeDefInfo):$ListGet(tTypeDefInfo, 2), 1:"")

		set tCategory = ..ClassifyNode(tRefType, tTypeDefNS, tTypeDefId, tNodeClass)

		set tCount = tCount + 1
		set pChildren(tCount) = $LB(tBrowseName, tDisplayName, tChildNS, tChildId, tChildIdType, tCategory, tRefType, tNodeClass)
		set pChildren(tCount, "typeDefNs") = tTypeDefNS
		set pChildren(tCount, "typeDefId") = tTypeDefId
	}
} Catch (e) {
	// Return whatever we have so far
}
Quit tCount

set tArray = []
Try {
	set tCount = ..WalkBrowseResults(pResults, .tChildren)

	for i=1:1:tCount {
		set tChild = tChildren(i)
		set tChildNS = $LI(tChild, 3)
		set tChildId = $LI(tChild, 4)

		// Display name: prefer displayName, fall back to browseName (unchanged behaviour)
		set tDisplayText = $LI(tChild, 2)
		if tDisplayText = "" set tDisplayText = $LI(tChild, 1)
		if tDisplayText = "" set tDisplayText = "Node"_tChildId

		set tCategory = $LI(tChild, 6)

		set tNode = {}
		set tNode.displayName = tDisplayText
		set tNode.nodeNs = tChildNS
		set tNode.nodeId = tChildId
		set tNode.nodeIdType = $LI(tChild, 5)
		set tNode.nodeCategory = tCategory
		set tNode.referenceType = $LI(tChild, 7)
		// The raw UA_NodeClass, for callers that want the spec value rather than
		// this UI's categories. "" when the library did not report one.
		set tNode.nodeClass = $LI(tChild, 8)
		set tNode.typeDefNs = tChildren(i, "typeDefNs")
		set tNode.typeDefId = tChildren(i, "typeDefId")
		// A real JSON boolean, so the probed and unprobed paths agree on type
		// and the declared TypeScript `hasChildren: boolean` holds either way.
		do tNode.%Set("hasChildren", ..CategoryHasChildren(tCategory), "boolean")

		do tArray.%Push(tNode)
	}
} Catch (e) {
	// Return whatever we have so far
}
Quit tArray

set tCount = 0
Try {
	set tRefList = $LI(pResult, 4)
	for i=1:1:$LL(tRefList) {
		set tRefTypeInfo = $LI($LI(tRefList, i), 1)
		if ..IsNonChildReference($LI(tRefTypeInfo, 1), $LI(tRefTypeInfo, 2)) continue
		set tCount = tCount + 1
	}
} Catch (e) {
	// An undecodable result counts as unknown, i.e. no children found here.
}
Quit tCount

Try {
	if pNodes.%Size() = 0 Quit

	set tTypes = "", tNss = "", tIds = ""
	for i=0:1:pNodes.%Size()-1 {
		set tNode = pNodes.%Get(i)
		set tTypes = tTypes _ $LB(tNode.nodeIdType)
		set tNss = tNss _ $LB(tNode.nodeNs)
		set tIds = tIds _ $LB(tNode.nodeId)
	}

	set tSC = pClient.Browse(.tResults, tTypes, tNss, tIds)
	Quit:$$$ISERR(tSC)

	set tBrowseData = $LI(tResults, 4)

	// Results are positional. A mismatched count means the pairing cannot be
	// trusted, so leave every guess alone rather than mislabel some other node.
	Quit:$LL(tBrowseData)'=pNodes.%Size()

	for i=0:1:pNodes.%Size()-1 {
		set tCount = ..CountChildReferences($LI(tBrowseData, i + 1))
		do pNodes.%Get(i).%Set("hasChildren", (tCount > 0), "boolean")
	}
} Catch (e) {
	// Keep the guesses.
}

// --- Node classes the heuristics could never identify on their own ---
if pNodeClass = $$$OpcuaNodeClassMethod Quit "method"
if pNodeClass = $$$OpcuaNodeClassView Quit "folder"

// A type-definition node (ObjectType, VariableType, ReferenceType, DataType) is
// a schema node, not an instance. Reached only when browsing the type hierarchy,
// since WalkBrowseResults drops HasTypeDefinition/HasSubtype references.
if (pNodeClass = $$$OpcuaNodeClassObjectType) || (pNodeClass = $$$OpcuaNodeClassVariableType) Quit "object"
if (pNodeClass = $$$OpcuaNodeClassReferenceType) || (pNodeClass = $$$OpcuaNodeClassDataType) Quit "object"

// --- Variable: split into variable vs property ---
if pNodeClass = $$$OpcuaNodeClassVariable {
	if pRefType = "HasProperty" Quit "property"
	if (pTypeDefNS = 0) && (pTypeDefId = 68) Quit "property"
	Quit "variable"
}

// --- Object: split into folder vs object ---
if pNodeClass = $$$OpcuaNodeClassObject {
	if (pTypeDefNS = 0) && (pTypeDefId = 61) Quit "folder"
	// No usable TypeDefinition — Organizes implies a folder-like grouping.
	if (pTypeDefNS = "") || (pTypeDefId = "") || (pTypeDefId = 0) {
		if pRefType = "Organizes" Quit "folder"
	}
	Quit "object"
}

// --- No nodeClass from the library: infer it, as before ---

// Properties are always metadata regardless of TypeDefinition
if pRefType = "HasProperty" Quit "property"

// No type definition info — fall back to reference type heuristic
if (pTypeDefNS = "") || (pTypeDefId = "") || (pTypeDefId = 0) {
	if pRefType = "Organizes" Quit "folder"
	Quit "object"
}

// Standard namespace (ns=0) — use well-known TypeDefinition IDs
if pTypeDefNS = 0 {
	// FolderType and subtypes
	if pTypeDefId = 61 Quit "folder"

	// PropertyType (should have been caught by HasProperty above, but just in case)
	if pTypeDefId = 68 Quit "property"

	// Variable types: BaseVariableType(62), BaseDataVariableType(63),
	// and all data-bearing subtypes
	if ..IsVariableTypeDef(pTypeDefId) Quit "variable"

	// Everything else in ns=0 is an Object type
	Quit "object"
}

// Custom namespace — use reference type as hint
if pRefType = "Organizes" Quit "folder"
// Custom types via HasComponent are likely variables (vendor data points)
Quit "variable"

// Core variable types
if (pTypeDefId = 62) Quit 1   ; BaseVariableType
if (pTypeDefId = 63) Quit 1   ; BaseDataVariableType

// DataType description/dictionary (metadata variables, but still Variable class)
if (pTypeDefId = 69) || (pTypeDefId = 72) Quit 1

// Server/diagnostic variable types
if (pTypeDefId >= 2137) && (pTypeDefId <= 2244) Quit 1

// DataAccess variable types: DataItemType..MultiStateDiscreteType
if (pTypeDefId = 2365) Quit 1  ; DataItemType
if (pTypeDefId = 2368) Quit 1  ; AnalogItemType
if (pTypeDefId = 2372) Quit 1  ; DiscreteItemType
if (pTypeDefId = 2373) Quit 1  ; TwoStateDiscreteType
if (pTypeDefId = 2376) Quit 1  ; MultiStateDiscreteType
if (pTypeDefId = 2380) Quit 1  ; ProgramDiagnosticType

// State machine variable types
if (pTypeDefId = 2755) || (pTypeDefId = 2760) Quit 1  ; StateVariableType, FiniteStateVariableType
if (pTypeDefId = 2762) || (pTypeDefId = 2767) Quit 1  ; TransitionVariableType, FiniteTransitionVariableType

// BuildInfoType
if (pTypeDefId = 3051) Quit 1

// TwoStateVariableType, ConditionVariableType
if (pTypeDefId = 8995) || (pTypeDefId = 9002) Quit 1

// MultiStateValueDiscreteType, OptionSetType
if (pTypeDefId = 11238) || (pTypeDefId = 11487) Quit 1

// ArrayItemType family
if (pTypeDefId >= 12021) && (pTypeDefId <= 12068) Quit 1

// Guard variables, BaseAnalogType, ProgramDiagnostic2Type
if (pTypeDefId = 15113) || (pTypeDefId = 15128) || (pTypeDefId = 15317) Quit 1
if (pTypeDefId = 15318) || (pTypeDefId = 15383) Quit 1

// SelectionListType, AlarmRateVariableType
if (pTypeDefId = 16309) || (pTypeDefId = 17277) Quit 1

// AnalogUnitType, AnalogUnitRangeType
if (pTypeDefId = 17497) || (pTypeDefId = 17570) Quit 1

// RationalNumberType, VectorType, ThreeDVectorType
if (pTypeDefId = 17709) || (pTypeDefId = 17714) || (pTypeDefId = 17716) Quit 1

// AudioVariableType
if (pTypeDefId = 17986) Quit 1

// Coordinate/orientation/frame types
if (pTypeDefId >= 18772) && (pTypeDefId <= 18791) Quit 1

// MultiStateDictionary types
if (pTypeDefId = 19077) || (pTypeDefId = 19084) Quit 1

// PubSubDiagnosticsCounterType
if (pTypeDefId = 19725) Quit 1

Quit 0

if (pCategory = "folder") || (pCategory = "object") Quit 1
// Variables can have child properties (e.g., EURange under AnalogItemType)
if pCategory = "variable" Quit 1
// Methods carry InputArguments/OutputArguments as HasProperty children.
if pCategory = "method" Quit 1
// A property is a leaf.
Quit 0

#dim tSC As %Status = $$$OK
Try {
	// Initialize library
	set tSC = ##class(OPCUA.Utils).Initialize()
	Quit:$$$ISERR(tSC)

	// Create and setup client
	set pClient = ##class(OPCUA.Client).%New()
	set tSC = pClient.Initialize()
	Quit:$$$ISERR(tSC)

	set tSC = pClient.SetupClient(, pSecurityMode, pClientURI, pCertPath, pKeyPath, pTrustDir, pCrlDir)
	Quit:$$$ISERR(tSC)

	set tSC = pClient.Connect(pURL, pUsername, pPassword)
	Quit:$$$ISERR(tSC)

} Catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

Try {
	if $IsObject($Get(pClient)) do pClient.Disconnect()
} Catch (e) {
	// Ignore disconnect errors
}

#dim tSC As %Status = $$$OK
#dim tClient As OPCUA.Client
Try {
	// Extract connection params
	set tSC = ##class(OPCUA.REST.ClientManager).ExtractConnectionParams(pBody, .tURL, .tSecMode, .tUser, .tPass, .tCert, .tKey, .tTrust, .tCrl, .tClientURI)
	Quit:$$$ISERR(tSC)

	// Measure connection time
	set tStart = $ZH

	// Connect
	set tSC = ##class(OPCUA.REST.ClientManager).Connect(.tClient, tURL, tSecMode, tUser, tPass, tCert, tKey, tTrust, tCrl, tClientURI)

	set tElapsed = $ZH - tStart
	set tElapsedMs = $FNumber(tElapsed * 1000, "", 0)

	set pResult = {}
	set pResult.url = tURL
	set pResult.responseTimeMs = +tElapsedMs

	if $$$ISERR(tSC) {
		set pResult.connected = 0
		set pResult.error = ##class(OPCUA.REST.Error).Text(tSC)
		// Reset status — we report the error in the JSON body
		set tSC = $$$OK
	} else {
		set pResult.connected = 1
	}

} Catch (e) {
	set tSC = e.AsStatus()
}

do ##class(OPCUA.REST.ClientManager).Disconnect($Get(tClient))
Quit tSC

if pBody.%Get("schemaClass") = "" {
	set pResult = {}
	set pResult.deployed = 0
	set pResult.compiled = 0
	set pResult.started = 0
	set pResult.productionClass = ..#ProductionClass
	Quit $$$ERROR($$$GeneralError, "Deploy request must include 'schemaClass'. Create the schema first with POST /schemas.")
}
Quit ..BindExistingSchema(pBody, .pResult)

#dim tSC As %Status = $$$OK
set pResult = {}
set pResult.deployed = 0
set pResult.compiled = 0
set pResult.started = 0
set pResult.productionClass = ..#ProductionClass
Try {
	set tSC = ..ValidateItemName(pBody.%Get("dataSourceName"))
	Quit:$$$ISERR(tSC)

	set tSchemaClass = pBody.%Get("schemaClass")

	if '##class(%Dictionary.CompiledClass).%ExistsId(tSchemaClass) {
		set tSC = ##class(OPCUA.REST.Error).NotFound("Schema '"_tSchemaClass_"' does not exist or is not compiled")
		Quit
	}
	if '##class(OPCUA.REST.SchemaService).IsSchema(tSchemaClass) {
		set tSC = $$$ERROR($$$GeneralError, "Class '"_tSchemaClass_"' is not an OPCUA.DataSource.DeviceSchema subclass")
		Quit
	}

	set tDevices = pBody.%Get("devices")
	if tDevices = "" set tDevices = pBody.%Get("deviceNodePaths")
	if tDevices = "" {
		set tSC = $$$ERROR($$$GeneralError, "No devices supplied — provide 'devices' as newline-separated nodepaths")
		Quit
	}

	// Which credentials the pipeline uses. Checked before the coverage check,
	// which has to connect the same way the pipeline will.
	set tSC = ..ResolveCredentials(pBody, .tCheckBody)
	Quit:$$$ISERR(tSC)

	// Fail early on an unusable device list rather than at connect time.
	// Report the per-line reasons, which are far more actionable than the summary.
	set tSC = ##class(OPCUA.DataSource.Resolver).ParseDeviceNodePaths(tDevices, .tParsed, .tParseErrors)
	if $$$ISERR(tSC) {
		set tMsg = "No usable device entries in 'devices'"
		for i=1:1:$LL(tParseErrors) { set tMsg = tMsg_" — "_$LI(tParseErrors, i) }
		set tSC = $$$ERROR($$$GeneralError, tMsg)
		Quit
	}

	// Every device must actually contribute a column. A device that browses to
	// zero matches writes nothing but NULLs for the life of the pipeline, so
	// catch it here rather than letting it quietly pad the table.
	set tSCUsable = ##class(OPCUA.REST.SchemaService).RequireUsableDevices(tCheckBody, tSchemaClass)
	if $$$ISERR(tSCUsable) {
		set tSC = tSCUsable
		Quit
	}

	set tItemName = pBody.%Get("dataSourceName")
	if tItemName = "" set tItemName = $Piece(tSchemaClass, ".", *)

	set tMode = pBody.%Get("mode")
	if (tMode '= "polling") && (tMode '= "subscription") set tMode = "polling"

	set tSC = ..EnsureProductionExists()
	Quit:$$$ISERR(tSC)

	// Config item names must stay unique. Checked here to fail fast, and again
	// under the edit lock in AddServiceItem.
	set tProd = ##class(Ens.Config.Production).%OpenId(..#ProductionClass)
	if $IsObject(tProd) && $IsObject(##class(OPCUA.REST.ProductionEdit).FindItem(tProd, tItemName)) {
		set tSC = ..DuplicateNameError(tItemName)
		Quit
	}
	kill tProd

	set tSC = ..AddServiceItem(pBody, tSchemaClass, tItemName, tMode, tDevices)
	Quit:$$$ISERR(tSC)

	set pResult.deployed = 1
	set pResult.compiled = 1
	set pResult.dataSourceClass = tSchemaClass
	set pResult.tableName = ##class(OPCUA.REST.SchemaService).TableName(tSchemaClass)
	set pResult.serviceItemName = tItemName
	set pResult.deviceCount = $LL(tParsed)

	// Deliberately not started. `started` stays 0 so a caller can see that
	// the pipeline exists but is not yet collecting.
	set pResult.enabled = 0

} Catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

#dim tSC As %Status = $$$OK
Try {
	// All deploys use the v2 row-source runtime services.
	if pMode = "subscription" {
		set tServiceClass = "OPCUA.Service.TCPSubscriptionRowSourceService"
	} else {
		set tServiceClass = "OPCUA.Service.TCPPollingRowSourceService"
	}

	// Create config item
	set tItem = ##class(Ens.Config.Item).%New()
	set tItem.Name = pDSName
	set tItem.ClassName = tServiceClass
	set tItem.PoolSize = 1
	// Portal categories: every pipeline we create carries "OPCUA" plus the
	// short name of its schema, so the Production Configuration page groups
	// our pipelines away from the hand-authored Examples, and groups the
	// pipelines sharing a schema together. Purely organisational — nothing
	// reads these back.
	//
	// A caller that sends "categories" owns the list outright, including the
	// right to drop "OPCUA" or to send none at all — hence %IsDefined rather
	// than a truth test, which would silently re-add the defaults to an
	// intentionally empty list. Absent means "decide for me", which is what
	// the Portal-only path and older clients rely on.
	if pBody.%IsDefined("categories") {
		set tItem.Category = ..NormalizeCategories(pBody.%Get("categories"))
	} else {
		do ..EnsureCategories(tItem, pDSClassName)
	}
	// Created switched off. Deploying is configuring; polling a live server and
	// writing rows is a separate, explicit act — so the operator gets a chance
	// to review the pipeline before it touches anything.
	set tItem.Enabled = 0
	set tItem.LogTraceEvents = 1

	// Add adapter settings
	do ..AddSetting(tItem, "Adapter", "DataSourceClass", pDSClassName)
	do ..AddSetting(tItem, "Adapter", "URL", pBody.%Get("url"))

	// The device list lives in the config item, so it is visible and editable
	// in the Management Portal — adding a device is a one-line edit here.
	do ..AddSetting(tItem, "Adapter", "DeviceNodePaths", pDeviceNodePaths)

	if pMode = "polling" {
		set tInterval = +pBody.%Get("callInterval")
		if tInterval < 1 set tInterval = 5
		do ..AddSetting(tItem, "Adapter", "CallInterval", tInterval)
	} else {
		set tPubInterval = +pBody.%Get("publishingInterval")
		if tPubInterval < 1 set tPubInterval = 1000
		do ..AddSetting(tItem, "Adapter", "RequestedPublishingInterval", tPubInterval)
		set tSampInterval = pBody.%Get("samplingInterval")
		if tSampInterval = "" set tSampInterval = 0
		do ..AddSetting(tItem, "Adapter", "RequestedSamplingInterval", +tSampInterval)
		set tQueueSize = +pBody.%Get("queueSize")
		if tQueueSize < 1 set tQueueSize = 5
		do ..AddSetting(tItem, "Adapter", "RequestedQueueSize", tQueueSize)
	}

	// Security settings
	set tSecMode = +pBody.%Get("securityMode")
	if tSecMode '= 3 set tSecMode = 1
	if tSecMode = 3 {
		do ..AddSetting(tItem, "Adapter", "SecurityMode", 3)
		do ..AddSettingIfNotEmpty(tItem, "Adapter", pBody, "clientURI", "ClientURI")
		do ..AddSettingIfNotEmpty(tItem, "Adapter", pBody, "certPath", "PublicCertificate")
		do ..AddSettingIfNotEmpty(tItem, "Adapter", pBody, "keyPath", "PrivateKey")
		do ..AddSettingIfNotEmpty(tItem, "Adapter", pBody, "trustDir", "TrustListDir")
		do ..AddSettingIfNotEmpty(tItem, "Adapter", pBody, "crlDir", "RevocationListDir")
	}

	// Credentials: an existing entry by ID, or a username (and password)
	// saved as a new entry below. Never a Username/Password setting, which
	// would put the password in the production class in plain text.
	set tCredId = pBody.%Get("credentials")
	set tUsername = pBody.%Get("username")
	set tNewCredId = ""
	if (tCredId = "") && (tUsername '= "") set (tCredId, tNewCredId) = ..CredentialsId(pDSName)
	do:tCredId'="" ..AddSetting(tItem, "Adapter", "Credentials", tCredId)
	// Refuse before taking the lock, so a missing privilege is the error the
	// caller sees.
	if (tNewCredId '= "") && '..CanWriteCredentials() {
		set tSC = ..NoCredentialsAccess("create credentials '"_tNewCredId_"'", "W")
		Quit
	}

	// Insert under the edit lock: reread the production, recheck the name,
	// create the entry, then one %Save and SaveToClass.
	set tSC = ##class(OPCUA.REST.ProductionEdit).Begin(.tProd, .tStamp)
	Quit:$$$ISERR(tSC)
	set tCreated = 0
	Try {
		if $IsObject(##class(OPCUA.REST.ProductionEdit).FindItem(tProd, pDSName)) {
			set tSC = ..DuplicateNameError(pDSName)
		} else {
			if tNewCredId '= "" {
				set tSC = ..CreateOwnedCredentials(tNewCredId, pDSName, tUsername, pBody.%Get("password"))
				set tCreated = $$$ISOK(tSC)
			}
			if $$$ISOK(tSC) {
				do tProd.Items.Insert(tItem)
				set tSC = ##class(OPCUA.REST.ProductionEdit).Commit(tProd, tStamp)
			}
		}
	} Catch (eEdit) {
		set tSC = eEdit.AsStatus()
	}
	// No pipeline, so no entry: take back the one just made for it, and say
	// so if that fails too.
	if $$$ISERR(tSC) && tCreated {
		set tSCUndo = ..DeleteOwnedCredentials(tNewCredId, pDSName)
		if $$$ISERR(tSCUndo) {
			set tSC = ##class(OPCUA.REST.Error).Make(500, "Pipeline not saved: "_##class(OPCUA.REST.Error).Text(tSC)_". The credentials '"_tNewCredId_"' made for it could not be removed: "_##class(OPCUA.REST.Error).Text(tSCUndo), tSC)
		}
	}
	do ##class(OPCUA.REST.ProductionEdit).End()

} Catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

set tKeep = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789.-_"
set tId = "OPCUA-"
for i=1:1:$Length(pItemName) {
	set tChar = $Extract(pItemName, i)
	set tId = tId_$Select(tKeep[tChar:tChar, 1:"_")
}
if $Length(tId) > ..#CredentialsIdMax {
	set tCrc = $ZConvert($ZHex($ZCRC($ZConvert(pItemName, "O", "UTF8"), 7)), "U")
	set tCrc = $Translate($Justify(tCrc, 8), " ", "0")
	set tId = $Extract(tId, 1, ..#CredentialsIdMax - 9)_"-"_tCrc
}
Quit tId

set pCheckBody = pBody
set tCredId = pBody.%Get("credentials")
if tCredId = "" {
	if (pBody.%Get("username") '= "") && '..CanWriteCredentials() {
		Quit ..NoCredentialsAccess("create credentials for this pipeline", "W")
	}
	Quit $$$OK
}
if pBody.%Get("username") '= "" {
	Quit ##class(OPCUA.REST.Error).BadRequest("Send either 'credentials' (an existing credentials ID) or 'username' and 'password', not both.")
}
set tSC = ..ReadCredentials(tCredId, .tUser, .tPassword)
Quit:$$$ISERR(tSC) tSC
set pCheckBody = {}.%FromJSON(pBody.%ToJSON())
do pCheckBody.%Set("username", tUser)
do pCheckBody.%Set("password", tPassword)
Quit $$$OK

set (pUser, pPassword) = ""
Quit:(pId="")||($ZConvert(pId, "L")="none") $$$OK
set tId = ..FindCredentialsId(pId)
if tId = "" {
	Quit ##class(OPCUA.REST.Error).BadRequest("Credentials '"_pId_"' do not exist in namespace "_$Namespace_". Create them in the Management Portal (Interoperability > Configure > Credentials) first.")
}
if '..CanReadCredentials() {
	Quit ..NoCredentialsAccess("read the password in credentials '"_tId_"'", "R")
}
set tCred = ##class(Ens.Config.Credentials).%OpenId(tId, 0, .tSC)
if '$IsObject(tCred) {
	Quit ##class(OPCUA.REST.Error).Make(500, "Cannot open credentials '"_tId_"'", tSC)
}
set pUser = tCred.Username, pPassword = tCred.Password
Quit $$$OK

Quit:'$System.Security.Check(..#CredentialsResource, "R") 0
try {
	set tOK = ($Data(^Ens.SecondaryData.Password) >= 0)
} catch {
	set tOK = 0
}
Quit tOK

// Ens matches credentials IDs in any case, so a taken ID in another case is
// taken.
set tTaken = ..FindCredentialsId(pId)
if tTaken '= "" {
	set tSC = ..CredentialsUsers(tTaken, .tUsers)
	Quit:$$$ISERR(tSC) tSC
	if '..OwnsCredentials(tTaken, pItemName) || (tUsers '= "") {
		Quit ##class(OPCUA.REST.Error).Conflict("Credentials '"_tTaken_"' already exist"_$Select(tUsers'="":" and are used by "_tUsers, 1:"")_", and are never overwritten. Choose a different pipeline name, or send 'credentials': '"_tTaken_"' to use them. If they are left over from a pipeline deleted in the Management Portal, delete them under Interoperability > Configure > Credentials, then deploy again.")
	}
	set pId = tTaken
}
Quit:'..CanWriteCredentials() ..NoCredentialsAccess("create credentials '"_pId_"'", "W")
set tSC = ##class(Ens.Config.Credentials).SetCredential(pId, pUsername, pPassword, (tTaken '= ""))
Quit:$$$ISERR(tSC) ##class(OPCUA.REST.Error).Make(500, "Could not create credentials '"_pId_"'", tSC)
set ^OPCUA.OwnedCredentials(pId) = pItemName
Quit $$$OK

set pUsers = "", tLower = $ZConvert(pId, "L")
#dim tSC As %Status = $$$OK
Try {
	&sql(DECLARE cCredProd CURSOR FOR SELECT ID INTO :tProdClass FROM Ens_Config.Production)
	&sql(OPEN cCredProd)
	if SQLCODE < 0 {
		set tSC = ##class(OPCUA.REST.Error).Make(500, "Failed to query Ens_Config.Production", $$$ERROR($$$SQLError, SQLCODE, $Get(%msg)))
		Quit
	}
	for {
		&sql(FETCH cCredProd)
		if SQLCODE = 100 Quit
		if SQLCODE < 0 {
			set tSC = ##class(OPCUA.REST.Error).Make(500, "Failed to query Ens_Config.Production", $$$ERROR($$$SQLError, SQLCODE, $Get(%msg)))
			Quit
		}
		set tProd = ##class(Ens.Config.Production).%OpenId(tProdClass, 0)
		if '$IsObject(tProd) {
			set tSC = ##class(OPCUA.REST.Error).Make(500, "Failed to open production '"_tProdClass_"'")
			Quit
		}
		for i=1:1:tProd.Items.Count() {
			set tItem = tProd.Items.GetAt(i)
			for j=1:1:tItem.Settings.Count() {
				set tS = tItem.Settings.GetAt(j)
				if (tS.Name = "Credentials") && ($ZConvert(tS.Value, "L") = tLower) {
					set pUsers = pUsers_$Select(pUsers="":"", 1:", ")_tItem.Name_" ("_tProdClass_")"
				}
			}
		}
	}
	&sql(CLOSE cCredProd)
} Catch (e) {
	set tSC = e.AsStatus()
	&sql(CLOSE cCredProd)
}
Quit tSC

set tOut = ""
if '$IsObject(pValue) {
	// Comma string (or empty): reuse the same splitting path as an array by
	// walking the pieces.
	for i=1:1:$Length(pValue, ",") {
		set tCat = $ZStrip($Piece(pValue, ",", i), "<>WC")
		continue:tCat=""
		continue:$Data(tSeen($ZConvert(tCat, "U")))
		set tSeen($ZConvert(tCat, "U")) = ""
		set tOut = $Select(tOut="":tCat, 1:tOut_","_tCat)
	}
	Quit tOut
}

set tIter = pValue.%GetIterator()
while tIter.%GetNext(.tKey, .tVal) {
	set tCat = $ZStrip($Translate($Get(tVal), ","), "<>WC")
	continue:tCat=""
	continue:$Data(tSeen($ZConvert(tCat, "U")))
	set tSeen($ZConvert(tCat, "U")) = ""
	set tOut = $Select(tOut="":tCat, 1:tOut_","_tCat)
}
Quit tOut

set tSchemaName = $Piece(pSchemaClass, ".", *)
set tWanted = $LB(..#PipelineCategory)
// A schema class is always present on a deploy, but do not stamp an empty
// piece if one ever is not — an empty category is dropped by the Portal anyway.
if tSchemaName '= "" set tWanted = tWanted_$LB(tSchemaName)

// Index what is already there, case-insensitively: the Portal treats
// categories as display strings, so "opcua" and "OPCUA" would show as two
// groups meaning one thing.
set tExisting = pItem.Category
for i=1:1:$Length(tExisting, ",") {
	set tCat = $ZStrip($Piece(tExisting, ",", i), "<>WC")
	continue:tCat=""
	set tHave($ZConvert(tCat, "U")) = ""
}

for i=1:1:$ListLength(tWanted) {
	set tCat = $ListGet(tWanted, i)
	continue:$Data(tHave($ZConvert(tCat, "U")))
	set tExisting = $Select(tExisting="":tCat, 1:tExisting_","_tCat)
	set tHave($ZConvert(tCat, "U")) = ""
}

set pItem.Category = tExisting

set tVal = pBody.%Get(pJsonKey)
if tVal '= "" {
	do ..AddSetting(pItem, pTarget, pSettingName, tVal)
}

set tSC = ##class(Ens.Director).GetProductionStatus(.tProdName, .tState)
Quit:$$$ISERR(tSC) tSC

// State: $$$eProductionStateRunning = 1, Stopped = 2, Suspended = 3, Troubled = 4
if (tProdName = ..#ProductionClass) && (tState = 1) {
	// Our production is already running — update it to pick up the new item
	Quit ##class(Ens.Director).UpdateProduction()
}

// Never stop someone else's production to make room for ours
set tSC = ..CheckNoOtherProduction()
Quit:$$$ISERR(tSC) tSC

// Start our production
Quit ##class(Ens.Director).StartProduction(..#ProductionClass)

Quit:pName="" $$$OK
if $Length(pName) > 128 {
	Quit ##class(OPCUA.REST.Error).BadRequest("Pipeline name is too long: "_$Length(pName)_" characters, at most 128.")
}
set tSC = ##class(Ens.Config.Item).%New().CheckForIllegalCharacters(pName)
if $$$ISERR(tSC) {
	do $System.Status.DecomposeStatus(tSC, .tErr)
	Quit ##class(OPCUA.REST.Error).BadRequest("Pipeline name '"_pName_"' is not valid: "_$Get(tErr(1, "param", 1), $System.Status.GetOneErrorText(tSC))_".")
}
Quit $$$OK

set tSC = ##class(Ens.Director).GetProductionStatus(.tProdName, .tState) Quit:$$$ISERR(tSC) tSC if (tProdName = "") || (tProdName = ..#ProductionClass) Quit $$$OK
// State: Running = 1, Suspended = 3, Troubled = 4 set tStateText = $Case(tState, 1:"running", 3:"suspended", 4:"troubled", :"") if tStateText = "" Quit $$$OK
Quit ##class(OPCUA.REST.Error).Conflict("Production '"_tProdName_"' is "_tStateText_" in namespace "_$Namespace_". A namespace runs one production at a time, and pipelines run in '"_..#ProductionClass_"'. Stop '"_tProdName_"' first; it was not changed.")

set tSC = $$$ERROR($$$GeneralError, pMessage, pHttp)
if (pCause '= "") && $$$ISERR(pCause) {
	set tSC = $$$ADDSC(tSC, pCause)
}
Quit tSC

Quit:$$$ISOK(pSC) 200
do $System.Status.DecomposeStatus(pSC, .tErr)
Quit:..Carried(pSC) +$Get(tErr(1, "param", 2))
for i=1:1:+$Get(tErr) {
	if (tErr(i, "code") '= ..GeneralCode()) && '..IsValidationCode(tErr(i, "code")) {
		Return 500
	}
}
Quit 400

Method.Description:
The message a response shows for <var>pSC</var>: for a status built by
<method>Make</method>, its own message (a cause appended to it is only logged);
otherwise <method>Text</method>.

Method.Implementation:
Quit:$$$ISOK(pSC) ""
do $System.Status.DecomposeStatus(pSC, .tErr)
set tText = ""
for i=1:1:+$Get(tErr) {
	set tCode = tErr(i, "code")
	if tCode = ..GeneralCode() {
		set tPart = $Get(tErr(i, "param", 1))
	} elseif tCode = ..ObjectScriptCode() {
		set tPart = "an unexpected internal error"
	} elseif ..IsValidationCode(tCode) {
		// "ERROR #5794: Datatype validation failed ..." without the prefix.
		set tPart = $Piece($System.Status.GetOneErrorText(pSC, i), ": ", 2, *)
	} else {
		set tPart = $System.Status.GetOneErrorText(pSC, i)
	}
	set tText = tText_$Select(tText="":"", 1:"; ")_tPart
}
Quit tText

#dim tSC As %Status = $$$OK
Try {
	set %response.OutputSessionToken = 0
	if %response.Language = "" set %response.Language = "en"
	set %response.ContentType = ..#CONTENTTYPE
	set:%request.Method'="OPTIONS" %response.Status = ..#HTTP401UNAUTHORIZED

	set tMatchURL = $Extract(%request.URL, $Length(%request.Application), *)
	set tRoute = ..DispatchMap(tMatchURL, %request.Method, .tVerbs, .tArgs)
	set tClass = $ListGet(tRoute, 3, $ClassName())
	set tSC = $ClassMethod(tClass, "ProcessCorsRequest", $ListGet(tRoute, 5, ""), $ListGet(tRoute, 4, ""))
	Quit:$$$ISERR(tSC)

	if %request.Method = "OPTIONS" {
		set tSC = ..OnHandleOptionsRequest(tMatchURL)
	}
} Catch (e) {
	set %response.Status = ..#HTTP401UNAUTHORIZED
	set tSC = $$$OK
}
// Login runs instead of Page, so the headers are not written yet.
do %response.WriteHTTPHeader()
if %request.Method '= "OPTIONS" {
	write {"status": "error", "error": "Sign-in failed"}.%ToJSON()
}
// As in the base method: an error status here would lose the 401.
Quit $$$OK

#dim tSC As %Status = $$$OK
Try {
	set tSC = ..GetRequestParams(.tBody)
	Quit:$$$ISERR(tSC)

	set tSC = ##class(OPCUA.REST.BrowseService).Browse(tBody, .tResult)
	Quit:$$$ISERR(tSC)
} Catch (e) {
