Quit ..Respond(tSC, $Get(tResult))

#dim tSC As %Status = $$$OK
Try {
	set tSC = ..GetRequestParams(.tBody)
	Quit:$$$ISERR(tSC)
	// The URL path is authoritative for these routes — clear any body
	// className that would otherwise shadow it.
	do tBody.%Set("className", "")
	do tBody.%Set("name", $ZConvert(pName, "I", "URL"))
	set tSC = ##class(OPCUA.REST.SchemaService).Validate(tBody, .tResult)
	Quit:$$$ISERR(tSC)
} Catch (e) {
	set tSC = e.AsStatus()
}
Quit ..Respond(tSC, $Get(tResult))

#dim tSC As %Status = $$$OK
Try {
	// Try to parse JSON body first
	if %request.Content '= "" {
		// Parse directly from Content (handles both streams and strings)
		set pBody = {}.%FromJSON(%request.Content)
		Quit
	}

	// Fall back to query parameters
	set pBody = {}
	set tParam = ""
	for {
		set tParam = $Order(%request.Data(tParam))
		if tParam = "" Quit
		set tVal = $Get(%request.Data(tParam, 1))
		do pBody.%Set(tParam, tVal)
	}
} Catch (e) {
	// The exception names a %FromJSON routine offset; the caller only needs
	// to know the body is not JSON.
	set tSC = ##class(OPCUA.REST.Error).BadRequest("Invalid request: the body is not valid JSON")
}
Quit tSC

Quit:$$$ISOK(pSC) ..SendOK(pData)
set tHttp = ##class(OPCUA.REST.Error).HttpCode(pSC)
if tHttp '= 500 {
	Quit ..SendError(tHttp, ##class(OPCUA.REST.Error).Message(pSC))
}

// yyyymmddThhmmss-job-n: no space, so it copies as one word, and the
// per-process counter keeps two errors in one second apart.
set tRef = $Translate($ZDateTime($Horolog, 8), " :", "T")_"-"_$Job_"-"_$Increment(^||OPCUA.REST("ref"))
set tWhere = ""
if $IsObject($Get(%request)) {
	set tWhere = " ("_%request.Method_" "_%request.URL_")"
}
do ..LogInternal("OPC UA REST error, reference "_tRef_tWhere_": "_$System.Status.GetErrorText(pSC))

if ##class(OPCUA.REST.Error).Carried(pSC) {
	set tMsg = ##class(OPCUA.REST.Error).Message(pSC)_" (Reference "_tRef_")"
} else {
	set tMsg = "Internal error. Reference "_tRef
}
Quit ..SendError(500, tMsg, tRef)

set tText = pText
try {
	do ..RequestSecrets(.tSecrets)
	set tSecret = ""
	for {
		set tSecret = $Order(tSecrets(tSecret), -1)
		Quit:tSecret=""
		set tText = $Replace(tText, tSecret, "*****")
	}
} catch e {
	// Could not read the request: log no request-derived text at all.
	set tText = $Piece(tText, ": ", 1)_": (error text withheld, the request could not be checked for secrets)"
}
do ##class(Ens.Util.Log).LogError($ClassName(), "Respond", $Extract(tText, 1, 32000))

Quit:'$IsObject(pNode)
set tIter = pNode.%GetIterator()
while tIter.%GetNext(.tKey, .tValue) {
	if $IsObject(tValue) {
		do ..CollectSecrets(tValue, .pSecrets)
	} elseif ($ZConvert(tKey, "L") [ "password") && (tValue '= "") {
		set pSecrets(tValue) = ""
	}
}

#dim tSC As %Status = $$$OK
set pResult = []
Try {
	// The same production that Toggle, Delete and Rebind edit.
	set tProdClass = ##class(OPCUA.REST.ProductionEdit).ProductionClass()
	if '##class(%Dictionary.ClassDefinition).%ExistsId(tProdClass) Quit

	set tProd = ##class(Ens.Config.Production).%OpenId(tProdClass)
	if '$IsObject(tProd) Quit

	set tSC = ##class(OPCUA.REST.ProductionEdit).ProductionStatus(.tRunningProd, .tProdState)
	Quit:$$$ISERR(tSC)
	set tProdRunning = (tRunningProd = tProdClass) && (tProdState = 1)

	for i=1:1:tProd.Items.Count() {
		set tCfgItem = tProd.Items.GetAt(i)
		// One pipeline that cannot be described must not hide the others: it is
		// listed with its error, as SchemaService.List lists an unreadable schema.
		Try {
			set tItem = ..ListEntry(tCfgItem, tProdRunning)
		} Catch (eItem) {
			set tItem = {"name": (tCfgItem.Name), "className": (tCfgItem.ClassName), "categories": []}
			set tItem.enabled = tCfgItem.Enabled
			set tItem.error = ##class(OPCUA.REST.Error).Text(eItem.AsStatus())
		}
		do pResult.%Push(tItem)
	}

} Catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

// Test seam (process-private, so not reachable over REST): force this item to fail.
if $Get(^||OPCUA.Tests("failPipelineItem")) = pCfgItem.Name {
	$$$ThrowStatus($$$ERROR($$$GeneralError, "Forced failure describing pipeline '"_pCfgItem.Name_"'"))
}
set tCfgItem = pCfgItem, tProdRunning = pProdRunning

set tItem = {}
set tItem.name = tCfgItem.Name
set tItem.className = tCfgItem.ClassName
set tItem.enabled = tCfgItem.Enabled
// Portal categories, as an array rather than the stored comma string:
// the console edits them as discrete chips, and splitting on the client
// would duplicate the trimming rules that already live server-side.
set tItem.categories = []
for c=1:1:$Length(tCfgItem.Category, ",") {
	set tCat = $ZStrip($Piece(tCfgItem.Category, ",", c), "<>WC")
	continue:tCat=""
	do tItem.categories.%Push(tCat)
}

// Determine mode and pipeline version from service class
if tItem.className = "OPCUA.Service.TCPSubscriptionRowSourceService" {
	set tItem.mode = "subscription"
	set tItem.pipelineVersion = 2
} elseif tItem.className = "OPCUA.Service.TCPSubscriptionService" {
	set tItem.mode = "subscription"
	set tItem.pipelineVersion = 1
} elseif tItem.className = "OPCUA.Service.TCPPollingRowSourceService" {
	set tItem.mode = "polling"
	set tItem.pipelineVersion = 2
} else {
	set tItem.mode = "polling"
	set tItem.pipelineVersion = 1
}

// Read settings from config item
set tItem.dataSourceClass = ..GetSettingValue(tCfgItem, "DataSourceClass")
set tItem.serverUrl = ..GetSettingValue(tCfgItem, "URL")
set tItem.callInterval = ..GetSettingValue(tCfgItem, "CallInterval")
set tItem.publishingInterval = ..GetSettingValue(tCfgItem, "RequestedPublishingInterval")
// The device list is now a plain setting, so surface it directly —
// editing a pipeline's devices is editing this string.
set tDeviceNodePaths = ..GetSettingValue(tCfgItem, "DeviceNodePaths")
set tItem.deviceNodePaths = tDeviceNodePaths

// Derive table name from DataSource class
if tItem.dataSourceClass '= "" {
	set tItem.tableName = ##class(OPCUA.REST.SchemaService).TableName(tItem.dataSourceClass)
}

if tProdRunning {
	set tItem.running = ##class(Ens.Director).IsItemEnabled(tItem.name, .tSCStatus)
} else {
	set tItem.running = 0
}
// Rows are a property of the table, not of the run state. Reporting 0
// for a stopped pipeline claimed its collected data was gone — and since
// a pipeline is now deployed stopped, that is the common case.
set tCount = ..GetRowCount(tItem.dataSourceClass)
do tItem.%Set("rowCount", tCount, $Select(tCount = "":"null", 1:"number"))

// Enabled is not the same as collecting: a service whose adapter fails
// to connect or resolve stays enabled and keeps retrying while writing
// nothing. Surface the adapter's own verdict so the UI can tell the two
// apart — this is what "started but silently collecting nothing" looked
// like before.
do ..GetHealth(tItem.name, tProdRunning, tCfgItem.Enabled, .tHealth, .tLastActivity, .tCycles)
set tItem.health = tHealth
set tItem.lastActivity = tLastActivity
set tItem.cycles = tCycles

set tItem.productionRunning = tProdRunning
set tItem.nodes = ..GetNodeNames(tItem.dataSourceClass)

if tItem.pipelineVersion = 2 {
	set tItem.rowSources = ..GetRowSourceInfo(tItem.dataSourceClass, tDeviceNodePaths)
}

Quit tItem

set tValue = ""
for i=1:1:pItem.Settings.Count() {
	set tSetting = pItem.Settings.GetAt(i)
	if tSetting.Name = pName {
		set tValue = tSetting.Value
		Quit
	}
}
Quit tValue

set pHealth = "ok"
set pLastActivity = ""
set pCycles = ""

if 'pProdRunning {
	set pHealth = "stopped"
	Quit
}
if 'pEnabled {
	set pHealth = "disabled"
	Quit
}

Try {
	set tStatus = $$$GetHostMonitor(pItemName, $$$eMonitorStatus)
	set pLastActivity = $$$GetHostMonitor(pItemName, $$$eMonitorLastActivity)
	// Completed cycles, which Ensemble already counts per host — this surfaces an
	// existing counter rather than adding bookkeeping. Zero rows after one cycle
	// is normal; zero rows after fifty is a problem, and the UI cannot tell those
	// apart from health alone.
	set pCycles = $$$GetHostMonitor(pItemName, $$$eMonitorCount)

	// No entry yet means the job exists but hasn't completed a cycle. Calling
	// that "ok" would claim success that hasn't happened.
	if tStatus = "" {
		set pHealth = "starting"
	} elseif tStatus = "OK" {
		set pHealth = "ok"
	} else {
		set pHealth = "error"
	}
} Catch (e) {
	// An unreadable monitor is not evidence of failure; leave it as-is.
}

set tCount = 0
Try {
	if pClassName = "" Quit
	// A schema class that is gone has an unknown count, not 0 rows.
	if '##class(%Dictionary.ClassDefinition).%ExistsId(pClassName) set tCount = "" Quit

	// $ZH is a monotonic second counter, so this needs no date arithmetic.
	set tNow = $ZH
	set tCached = $Get(^IRIS.Temp.OPCUARowCount(pClassName))
	if tCached '= "" {
		set tAt = $ListGet(tCached, 1)
		if (tNow - tAt) < ..#RowCountTTL {
			set tCount = $ListGet(tCached, 2)
			Quit
		}
	}
	// Quoted, so a reserved word as schema or table name (Group) still parses.
	// Dynamic SQL: an account without SELECT on the table (the installer's
	// OPCUA_API role) gets a 403 here, caught below as an unknown count.
	set tTable = ##class(OPCUA.REST.SchemaService).QuotedTableName(pClassName)
	set tRS = ##class(OPCUA.Utils).ExecQuery("SELECT COUNT(*) FROM "_tTable)
	if tRS.%Next() set tCount = tRS.%GetData(1)
	set ^IRIS.Temp.OPCUARowCount(pClassName) = $ListBuild(tNow, tCount)
} Catch (e) {
	set tCount = ""
}
Quit tCount

// No Try: an unexpected error goes to List's Catch and is reported, rather
// than showing the pipeline with no nodes.
set tNodes = []
Quit:pClassName="" tNodes
// Use compiled class info (CompiledProperty) which has parameter access
set tClassDef = ##class(%Dictionary.CompiledClass).%OpenId(pClassName)
Quit:'$IsObject(tClassDef) tNodes
for i=1:1:tClassDef.Properties.Count() {
	set tProp = tClassDef.Properties.GetAt(i)
	// Get OPCUANODENAME from property parameters
	set tNodeName = tProp.Parameters.GetAt("OPCUANODENAME")
	if tNodeName '= "" {
		set tNodeInfo = {}
		set tNodeInfo.property = tProp.Name
		set tNodeInfo.nodeId = tNodeName
		do tNodes.%Push(tNodeInfo)
	}
}
Quit tNodes

#dim tSC As %Status = $$$OK
set pResult = {}
Try {
	set tName = pBody.%Get("name")
	if tName = "" {
		set tSC = $$$ERROR($$$GeneralError, "Missing pipeline name")
		Quit
	}

	set tSC = ##class(OPCUA.REST.ProductionEdit).Begin(.tProd, .tStamp)
	Quit:$$$ISERR(tSC)
	Try {
		set tItem = ##class(OPCUA.REST.ProductionEdit).FindItem(tProd, tName)
		if '$IsObject(tItem) {
			set tSC = ##class(OPCUA.REST.Error).NotFound("Pipeline '"_tName_"' not found")
		} else {
			set tNewState = 'tItem.Enabled
			// Check before saving, so a refused enable leaves the pipeline disabled
			if tNewState set tSC = ##class(OPCUA.REST.DeployService).CheckNoOtherProduction()
			if $$$ISOK(tSC) {
				set tItem.Enabled = tNewState
				set tSC = ##class(OPCUA.REST.ProductionEdit).Commit(tProd, tStamp)
			}
		}
	} Catch (eEdit) {
		set tSC = eEdit.AsStatus()
	}
	do ##class(OPCUA.REST.ProductionEdit).End()
	Quit:$$$ISERR(tSC)

	set pResult.name = tName
	set pResult.enabled = tNewState

	// Update the running production, or start it when enabling a pipeline
	// while it is not running.
	set tSC = ##class(OPCUA.REST.ProductionEdit).ApplyToRunning(.tRestarted, .tNote)
	if $$$ISOK(tSC) && 'tRestarted && tNewState {
		set tSC = ##class(OPCUA.REST.DeployService).StartOrUpdateProduction()
		if $$$ISOK(tSC) set tRestarted = 1, tNote = ""
	}
	set pResult.restarted = tRestarted
	set pResult.restartNote = tNote
	if $$$ISERR(tSC) {
		set tSC = ##class(OPCUA.REST.Error).Make(500, "Pipeline "_$Select(tNewState:"enabled",1:"disabled")_" and saved, but the production could not be updated: "_##class(OPCUA.REST.Error).Text(tSC), tSC)
	}

} Catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

#dim tSC As %Status = $$$OK
set pResult = {}
Try {
	set tName = pBody.%Get("name")
	if tName = "" {
		set tSC = $$$ERROR($$$GeneralError, "Missing pipeline name")
		Quit
	}

	// A pipeline whose credentials entry deploy created takes the entry with
	// it, which needs %Ens_Credentials:W. Without it, refuse before anything
	// is removed, rather than delete the pipeline and orphan the entry (every
	// redeploy under the name would then get 409).
	set tSC = ..CheckCanDeleteCredentials(tName)
	Quit:$$$ISERR(tSC)

	set tDSClass = "", tItemId = "", tCredId = ""
	set tSC = ##class(OPCUA.REST.ProductionEdit).Begin(.tProd, .tStamp)
	Quit:$$$ISERR(tSC)
	Try {
		set tCfgItem = ##class(OPCUA.REST.ProductionEdit).FindItem(tProd, tName, .tFoundIdx)
		if '$IsObject(tCfgItem) {
			set tSC = ##class(OPCUA.REST.Error).NotFound("Pipeline '"_tName_"' not found in production")
		} else {
			// Capture the schema and the row ID before removing
			set tDSClass = ..GetSettingValue(tCfgItem, "DataSourceClass")
			set tCredId = ..GetSettingValue(tCfgItem, "Credentials")
			set tItemId = tCfgItem.%Id()
			do tProd.Items.RemoveAt(tFoundIdx)
			set tSC = ##class(OPCUA.REST.ProductionEdit).Commit(tProd, tStamp)
		}
	} Catch (eEdit) {
		set tSC = eEdit.AsStatus()
	}
	do ##class(OPCUA.REST.ProductionEdit).End()
	Quit:$$$ISERR(tSC)

	// Delete the config item row to prevent orphans. The pipeline is already
	// gone from the production, so a failure here is reported with the other
	// follow-ups below, which still run.
	set tSCItem = $$$OK
	if tItemId '= "" {
		Try {
			set tSCItem = ##class(Ens.Config.Item).%DeleteId(tItemId)
		} Catch (eItem) {
			set tSCItem = eItem.AsStatus()
		}
	}

	// The credentials entry goes too, but only if deploy created it for this
	// pipeline. An entry the pipeline merely pointed at belongs to someone else.
	set tSCCred = ##class(OPCUA.REST.DeployService).DeleteOwnedCredentials(tCredId, tName)

	// A running production stops the removed item's job when it updates.
	// EnableConfigItem is not used to stop it first: it saves the production
	// itself, outside our edit, which Commit would then refuse as stale.
	set tSCApply = ##class(OPCUA.REST.ProductionEdit).ApplyToRunning(.tRestarted, .tNote)

	// Report every follow-up that failed, not just the last.
	set tFailed = "", tCause = $$$OK
	if $$$ISERR(tSCItem) {
		set tFailed = "its config item row "_tItemId_" could not be removed: "_##class(OPCUA.REST.Error).Text(tSCItem)
		set tCause = $$$ADDSC(tCause, tSCItem)
	}
	if $$$ISERR(tSCCred) {
		set tFailed = tFailed_$Select(tFailed="":"", 1:"; and ")_"its credentials '"_tCredId_"' could not be deleted: "_##class(OPCUA.REST.Error).Text(tSCCred)
		set tCause = $$$ADDSC(tCause, tSCCred)
	}
	if $$$ISERR(tSCApply) {
		set tFailed = tFailed_$Select(tFailed="":"", 1:"; and ")_"the running production could not be updated: "_##class(OPCUA.REST.Error).Text(tSCApply)
		set tCause = $$$ADDSC(tCause, tSCApply)
	}
	if tFailed '= "" {
		set tSC = ##class(OPCUA.REST.Error).Make(500, "Pipeline deleted, but "_tFailed, tCause)
	}

	set pResult.deleted = 1
	set pResult.name = tName

	// Report the schema and whether it is now unused, so a caller that wants
	// to clean it up knows it can — without this being done behind their back.
	set pResult.schemaClass = tDSClass
	set pResult.schemaRetained = 1
	if tDSClass '= "" {
		set tSC2 = ##class(OPCUA.REST.SchemaService).MapSchemaUsage(.tUsage)
		if $$$ISOK(tSC2) {
			set pResult.schemaStillUsedBy = ##class(OPCUA.REST.SchemaService).UsageArray(.tUsage, tDSClass)
		} else {
			// Usage check failed, report empty — the schema is retained anyway
			set pResult.schemaStillUsedBy = []
		}
	} else {
		set pResult.schemaStillUsedBy = []
	}

} Catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

#dim tSC As %Status = $$$OK
set pResult = {}
set pResult.updated = 0
Try {
	set tName = pBody.%Get("name")
	if tName = "" {
		set tSC = $$$ERROR($$$GeneralError, "Missing pipeline name")
		Quit
	}

	set tDevices = pBody.%Get("devices")
	if tDevices = "" set tDevices = pBody.%Get("deviceNodePaths")
	if tDevices = "" {
		set tSC = $$$ERROR($$$GeneralError, "No devices supplied — provide 'devices' as newline-separated nodepaths")
		Quit
	}

	// Reject an unusable list here rather than letting the service fail at its
	// next connect, and report the per-line reasons.
	set tSC = ##class(OPCUA.DataSource.Resolver).ParseDeviceNodePaths(tDevices, .tParsed, .tParseErrors)
	if $$$ISERR(tSC) {
		set tMsg = "No usable device entries in 'devices'"
		for i=1:1:$LL($Get(tParseErrors)) { set tMsg = tMsg_" — "_$LI(tParseErrors, i) }
		set tSC = $$$ERROR($$$GeneralError, tMsg)
		Quit
	}

	// Same gate as deploy: a device that resolves no columns would only add
	// all-NULL rows. The schema and endpoint come from the pipeline itself, so a
	// rebind body needs to carry nothing but the device list.
	set tSC = ..DescribeItem(tName, .tSchemaClass, .tItemURL, .tConn)
	Quit:$$$ISERR(tSC)

	do tConn.%Set("devices", tDevices)
	set tSC = ##class(OPCUA.REST.SchemaService).RequireUsableDevices(tConn, tSchemaClass)
	Quit:$$$ISERR(tSC)

	// Devices and categories change in one locked open and save. Categories
	// ride along with a rebind, since editing a pipeline is where a user would
	// expect to change them. Absent leaves them alone, an empty array clears
	// them. Organisational only, so an odd list cannot break collection, which
	// is why this is a plain overwrite beyond normalising the delimiter.
	set tFields = ""
	if pBody.%IsDefined("categories") {
		set tFields = {"Category": (##class(OPCUA.REST.DeployService).NormalizeCategories(pBody.%Get("categories")))}
	}
	set tSC = ##class(OPCUA.REST.ProductionEdit).UpdateItem(tName, {"Adapter": {"DeviceNodePaths": (tDevices)}}, tFields)
	Quit:$$$ISERR(tSC)

	// The adapter re-resolves on every (re)connect, so updating the running
	// production is all that is needed for the new device list to take
	// effect. restarted is 1 only when that update really happened.
	set tSC = ##class(OPCUA.REST.ProductionEdit).ApplyToRunning(.tRestarted, .tNote)
	set pResult.restarted = tRestarted
	set pResult.restartNote = tNote
	if $$$ISERR(tSC) {
		set tSC = ##class(OPCUA.REST.Error).Make(500, "Device list saved, but the running pipeline could not be restarted: "_##class(OPCUA.REST.Error).Text(tSC), tSC)
	}

	set pResult.updated = 1
	set pResult.name = tName
	set pResult.deviceCount = $LL(tParsed)

} Catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

set pSchemaClass = ""
set pURL = ""
set pConn = {}

set tProdClass = ##class(OPCUA.REST.ProductionEdit).ProductionClass()
set tProd = ##class(Ens.Config.Production).%OpenId(tProdClass)
if '$IsObject(tProd) {
	Quit ##class(OPCUA.REST.Error).Make(500, "Cannot open production: "_tProdClass)
}

set tItem = ##class(OPCUA.REST.ProductionEdit).FindItem(tProd, pItemName)
if '$IsObject(tItem) {
	Quit ##class(OPCUA.REST.Error).NotFound("Pipeline '"_pItemName_"' not found in production")
}

set pSchemaClass = ..GetSettingValue(tItem, "DataSourceClass")
set pURL = ..GetSettingValue(tItem, "URL")
if pSchemaClass = "" {
	Quit ##class(OPCUA.REST.Error).Make(500, "Pipeline '"_pItemName_"' has no DataSourceClass setting")
}

do pConn.%Set("url", pURL)
// Setting name → the JSON key ExtractConnectionParams expects.
set tMap("SecurityMode") = "securityMode", tMap("ClientURI") = "clientURI"
set tMap("PublicCertificate") = "certPath", tMap("PrivateKey") = "keyPath"
set tMap("TrustListDir") = "trustDir", tMap("RevocationListDir") = "crlDir"
set tSetting = ""
for {
	set tSetting = $Order(tMap(tSetting))
	quit:tSetting=""
	set tVal = ..GetSettingValue(tItem, tSetting)
	do:tVal'="" pConn.%Set(tMap(tSetting), tVal)
}

// The username and password live in the item's credentials entry. The
// check connects as the pipeline does, so a missing entry is an error, not
// an anonymous connect.
set tCredId = ..GetSettingValue(tItem, "Credentials")
if tCredId '= "" {
	set tSC = ##class(OPCUA.REST.DeployService).ReadCredentials(tCredId, .tUser, .tPassword)
	if $$$ISERR(tSC) {
		Quit ##class(OPCUA.REST.Error).Make(##class(OPCUA.REST.Error).HttpCode(tSC), "Pipeline '"_pItemName_"': "_##class(OPCUA.REST.Error).Text(tSC), tSC)
	}
	do:tUser'="" pConn.%Set("username", tUser)
	do:tPassword'="" pConn.%Set("password", tPassword)
}
Quit $$$OK

// No Try: an unexpected error goes to List's Catch and is reported, rather
// than silently listing only the devices handled before it.
set tResult = []
Quit:pDeviceNodePaths="" tResult

// Status ignored: a list with no usable device (all comments, which is how a
// pipeline is paused from the Portal, or all invalid) is an error there, but
// here it is just a pipeline with no devices. Deploy and the adapter report
// unusable lines.
do ##class(OPCUA.DataSource.Resolver).ParseDeviceNodePaths(pDeviceNodePaths, .tDevices, .tErrors)
Quit:$LL($Get(tDevices))=0 tResult

// Schema columns, in the same storage order the runtime uses. A schema that
// cannot be read (deleted outside the console) still lists its devices,
// with no columns: the dashboard shows only device paths and counts.
set tSC = ##class(OPCUA.DataSource.Resolver).GetSchemaColumns(pClassName, .tColumns, .tFolders)
if $$$ISERR(tSC) set tColumns = 0

for i=1:1:$LL(tDevices) {
	set tDev = $LI(tDevices, i)
	set tInfo = {}
	set tInfo.path = $LI(tDev, 4)
	set tInfo.nodeNs = $LI(tDev, 1)
	set tInfo.nodeId = $LI(tDev, 2)
	set tInfo.nodeIdType = $LI(tDev, 3)

	set tChildren = []
	for c=1:1:tColumns {
		set tCol = tColumns(c)
		set tFolderName = $LI(tCol, 5)
		set tNodeName = $LI(tCol, 3)

		set tChild = {}
		set tChild.displayName = tNodeName
		set tChild.nodeNs = $LI(tCol, 2)
		// Nodes are resolved by name at connect time, so there is no
		// stored absolute node id to report here.
		set tChild.nodeId = ""
		set tChild.nodeIdType = ""

		set tRelPath = ##class(%DynamicArray).%New()
		if tFolderName '= "" do tRelPath.%Push(tFolderName)
		do tRelPath.%Push(tNodeName)
		set tChild.relativePath = tRelPath

		do tChildren.%Push(tChild)
	}
	set tInfo.childNodes = tChildren

	do tResult.%Push(tInfo)
}
Quit tResult

#dim tSC As %Status = $$$OK
Try {
	set tClassDef = ##class(%Dictionary.CompiledClass).%OpenId(pClassName)
	if '$IsObject(tClassDef) Quit

	for i=1:1:tClassDef.Properties.Count() {
		set tProp = tClassDef.Properties.GetAt(i)
		set tType = tProp.Type
		// Skip OPCUA.Types.* (these are framework serial objects, not ours)
		if $Extract(tType, 1, 12) = "OPCUA.Types." continue
		// Skip standard types
		if $Extract(tType, 1) = "%" continue
		// Check if it extends %SerialObject
		set tIsSerial = 0
		Try {
			set tIsSerial = $classmethod(tType, "%Extends", "%SerialObject")
		} Catch (eInner) {
			// Type class may not exist: then it is no serial class of ours to delete.
		}
		continue:'tIsSerial

		// Check if the serial class name matches the generated pattern
		continue:'..IsGeneratedSerialClass(pClassName, tType)

		// Check if any other class uses this serial class. A failed check
		// throws to the outer Catch, so nothing is deleted on a guess.
		continue:..SerialClassIsShared(pClassName, tType)

		// This is a pipeline-generated serial class that is not shared — delete it.
		// Quit leaves the loop: a later successful delete must not overwrite tSC.
		if ##class(%Dictionary.ClassDefinition).%ExistsId(tType) {
			set tSC = $System.OBJ.Delete(tType, "-d")
			Quit:$$$ISERR(tSC)
		}
	}
} Catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

// Generated serial classes are nested under the main class: OPCUA.DS.Foo.BarType
// Main class: OPCUA.DS.Foo, serial: OPCUA.DS.Foo.<something>Type
if $Extract(pSerialClass, 1, $Length(pMainClass)+1) '= (pMainClass_".") {
	Return 0
}
if $Extract(pSerialClass, *-3, *) '= "Type" {
	Return 0
}
Return 1

// Embedded SQL checks no SQL privilege, so this works for an account with only
// the installer's OPCUA_API role (dynamic SQL gave it SQLCODE -99). A failed
// query throws: reading it as "not shared" would delete a class another schema
// still uses.
set tParent = ""
&sql(SELECT TOP 1 Parent INTO :tParent FROM %Dictionary.CompiledProperty WHERE Type = :pSerialClass AND Parent <> :pMainClass)
if SQLCODE < 0 $$$ThrowStatus($$$ERROR($$$SQLError, SQLCODE, $Get(%msg)))
// SQLCODE 0: at least one other class uses this serial class.
Quit (SQLCODE = 0)

set pProd = "", pStamp = ""
lock +^OPCUA.ProductionEdit:pTimeout
if '$Test Quit ##class(OPCUA.REST.Error).Conflict("Another change to the pipelines is in progress; try again.")

#dim tSC As %Status = $$$OK
Try {
	set tClass = ..ProductionClass()
	// Read the stamp before the data. A save in between then makes Commit
	// refuse a fresh copy, which is safe. The other order would miss it.
	set pStamp = ..Stamp(tClass)
	set pProd = ##class(Ens.Config.Production).%OpenId(tClass, 0, .tSC)
	if '$IsObject(pProd) {
		set tSC = ##class(OPCUA.REST.Error).Make(500, "Cannot open production: "_tClass, tSC)
		Quit
	}
	// %OpenId hands back an object this process already holds, unchanged.
	// Reread it, and its items, so the edit starts from what is on disk.
	set tSC = pProd.%Reload()
	Quit:$$$ISERR(tSC)
	for i=1:1:pProd.Items.Count() {
		set tSC = pProd.Items.GetAt(i).%Reload()
		Quit:$$$ISERR(tSC)
	}
} Catch (e) {
	set tSC = e.AsStatus()
}
if $$$ISERR(tSC) {
	set pProd = ""
	do ..End()
}
Quit tSC

#dim tSC As %Status = $$$OK
Try {
	if ..Stamp(pProd.Name) '= pStamp {
		set tSC = ##class(OPCUA.REST.Error).Conflict("The pipeline production was changed by someone else (for example in the Management Portal); reload and try again.")
		Quit
	}
	set tSC = pProd.%Save()
	Quit:$$$ISERR(tSC)
	set tSC = pProd.SaveToClass()
} Catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

set tSC = ..Begin(.tProd, .tStamp)
Quit:$$$ISERR(tSC) tSC
Try {
	set tItem = ..FindItem(tProd, pItemName)
	if '$IsObject(tItem) {
		set tSC = ##class(OPCUA.REST.Error).NotFound("Pipeline '"_pItemName_"' not found in production")
		Quit
	}
	if $IsObject(pSettings) {
		set tTargets = pSettings.%GetIterator()
		while tTargets.%GetNext(.tTarget, .tValues) {
			set tIter = tValues.%GetIterator()
			while tIter.%GetNext(.tName, .tValue) {
				do ..SetSetting(tItem, tTarget, tName, tValue)
			}
		}
	}
	if $IsObject(pFields) {
		set tIter = pFields.%GetIterator()
		while tIter.%GetNext(.tName, .tValue) {
			set $Property(tItem, tName) = tValue
		}
	}
	set tSC = ..Commit(tProd, tStamp)
} Catch (e) {
	set tSC = e.AsStatus()
}
do ..End()
Quit tSC

set pIndex = 0
for i=1:1:pProd.Items.Count() {
	if pProd.Items.GetAt(i).Name = pItemName {
		set pIndex = i
		return pProd.Items.GetAt(i)
	}
}
Quit ""

for i=1:1:pItem.Settings.Count() {
	set tSetting = pItem.Settings.GetAt(i)
	if (tSetting.Name = pName) && (tSetting.Target = pTarget) {
		set tSetting.Value = pValue
		return
	}
}
set tSetting = ##class(Ens.Config.Setting).%New()
set tSetting.Target = pTarget
set tSetting.Name = pName
set tSetting.Value = pValue
do pItem.Settings.Insert(tSetting)

set tFake = $Get(^||OPCUA.Tests("productionStatus"))
if tFake '= "" {
	set pName = $ListGet(tFake, 1), pState = $ListGet(tFake, 2)
	Quit $$$OK
}
Quit ##class(Ens.Director).GetProductionStatus(.pName, .pState)

set pRestarted = 0, pNote = ""
set tSC = ..ProductionStatus(.tName, .tState)
Quit:$$$ISERR(tSC) tSC

if tName '= ..ProductionClass() {
	set pNote = "The pipeline production is not running, so the change takes effect when it starts."
	Quit $$$OK
}
// State: Running = 1, Stopped = 2, Suspended = 3, Troubled = 4
if tState = 2 {
	set pNote = "The pipeline production is stopped, so the change takes effect when it starts."
	Quit $$$OK
}
if tState '= 1 {
	set tText = $Case(tState, 3:"suspended", 4:"troubled", :"in state "_tState)
	Quit $$$ERROR($$$GeneralError, "production '"_tName_"' is "_tText)
}
set tSC = ##class(Ens.Director).UpdateProduction()
Quit:$$$ISERR(tSC) tSC
set pRestarted = 1
Quit $$$OK

#dim tSC As %Status = $$$OK
#dim tClient As OPCUA.Client
Try {
	// Extract connection params
	set tSC = ##class(OPCUA.REST.ClientManager).ExtractConnectionParams(pBody, .tURL, .tSecMode, .tUser, .tPass, .tCert, .tKey, .tTrust, .tCrl, .tClientURI)
	Quit:$$$ISERR(tSC)

	// Node parameters
	set tNsVal = pBody.%Get("nodeNs")
	set tNodeNS = $Select(tNsVal="":0, 1:+tNsVal)
	set tNodeId = pBody.%Get("nodeId")
	if tNodeId = "" {
		set tSC = $$$ERROR($$$GeneralError, "Missing required parameter: nodeId")
		Quit
	}
	set tTypeVal = pBody.%Get("nodeIdType")
	set tNodeIdType = $Select(tTypeVal="":0, 1:+tTypeVal)

	// Auto-detect string vs numeric node ID
	if (tNodeIdType = 0) && ($Match(tNodeId, "^\d+$")) {
		set tNodeId = +tNodeId
	} elseif tNodeIdType = 0 {
		set tNodeIdType = $$$OpcuaNodeIdTypeString
	}

	// Connect
	set tSC = ##class(OPCUA.REST.ClientManager).Connect(.tClient, tURL, tSecMode, tUser, tPass, tCert, tKey, tTrust, tCrl, tClientURI)
	Quit:$$$ISERR(tSC)

	// Read and parse — delegated to a separate method so its Try/Catch
	// reliably catches <NULL VALUE> from the C++ $ZF layer
	set tSC = ..SafeReadAndParse(tClient, tNodeNS, tNodeId, tNodeIdType, pBody.%Get("nodeId"), .pResult)
	Quit:$$$ISERR(tSC)

} Catch (e) {
	set tSC = e.AsStatus()
}

do ##class(OPCUA.REST.ClientManager).Disconnect($Get(tClient))
Quit tSC

#dim tSC As %Status = $$$OK
set pResult = {}
set pResult.nodeNs = pNodeNS
set pResult.nodeId = pOrigNodeId
set pResult.nodeIdType = pNodeIdType

// Step 1: Read value attribute
set tReadOK = 0
set tResults = ""
set tSC = ..SafeReadValue(pClient, pNodeId, pNodeNS, pNodeIdType, .tResults, .tReadOK)

// Step 2: Infer type (only if read succeeded)
set tInferredType = ""
if tReadOK {
	set tInferredType = ..SafeInferType(pClient, pNodeNS, pNodeId, pNodeIdType)
}
if tInferredType = "" set tInferredType = "OPCUA.Types.StringDataValue"

// Step 3: Parse results
if 'tReadOK {
	set pResult.value = ""
	set pResult.readError = "Failed to read node: "_$Select($$$ISERR(tSC):##class(OPCUA.REST.Error).Text(tSC), 1:"no value returned")
	set pResult.inferredType = tInferredType
	Quit $$$OK
}

// Parse read results: $LB(errCode, sourceTS, serverTS, status, value)
if $ListValid($Get(tResults)) && ($ListLength(tResults) >= 5) {
	set tErrCode = $ListGet(tResults, 1)
	if tErrCode = 0 {
		set pResult.value = ..SafeExtractValue($ListGet(tResults, 5))
		set pResult.sourceTimestamp = $ListGet(tResults, 2)
		set pResult.serverTimestamp = $ListGet(tResults, 3)
		set pResult.statusCode = $ListGet(tResults, 4)
	} else {
		set pResult.value = ""
		set pResult.readError = "Error code: "_tErrCode
	}
} else {
	set pResult.value = ""
	set pResult.readError = "Unexpected result format"
}

set pResult.inferredType = tInferredType
Quit $$$OK

set pOK = 0
set pResults = ""
Try {
	set tSC = pClient.ReadValueAttribute(.pResults, pNodeId, pNodeNS, pNodeIdType)
	if $$$ISOK(tSC) set pOK = 1
} Catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

set tType = ""
Try {
	set tType = ##class(OPCUA.DataSource.Generator).InferType(pClient, pNodeNS, pNodeId, pNodeIdType)
} Catch (e) {
	// Fall back to empty (caller defaults to StringDataValue)
}
Quit tType

set tResult = pValue
Try {
	if $ListValid(pValue) && ($ListLength(pValue) > 0) {
		set tArr = []
		for i=1:1:$ListLength(pValue) {
			do tArr.%Push($ListGet(pValue, i))
		}
		set tResult = tArr
	}
} Catch (e) {
	// Fall through to return raw value
}
Quit tResult

Method.Description:
POST /schemas — create a schema from a column list.
Body: { className | name target class ("OPCUA.DS.AirConditioner", or "AirConditioner" combined with packagePath) packagePath optional package when only `name` is given dataSourceName optional OPCUADATASOURCE value (defaults to the short name) defaultNamespace optional OPC UA namespace index for columns that omit one columns[] { displayName, inferredType, relativePath[], nodeNs } includeServerTimestamp optional, default true. false types every column as an OPCUA.Types.NoServerTS measurement, so the table has no *_ServerTS columns }
Deliberately touches no production and writes no device metadata.

Method.Implementation:
#dim tSC As %Status = $$$OK
set pResult = {}
set pResult.created = 0
Try {
	set tColumns = pBody.%Get("columns")
	if '$IsObject($Get(tColumns)) || (tColumns.%Size() = 0) {
		set tSC = $$$ERROR($$$GeneralError, "No columns defined")
		Quit
	}

	set tSC = ..ResolveClassName(pBody, .tClassName)
	Quit:$$$ISERR(tSC)

	set tDataSourceName = pBody.%Get("dataSourceName")
	if tDataSourceName = "" set tDataSourceName = $Piece(tClassName, ".", *)

	if ##class(%Dictionary.ClassDefinition).%ExistsId(tClassName) {
		set tSC = ##class(OPCUA.REST.Error).Conflict("Class '"_tClassName_"' already exists. Choose a different name.")
		Quit
	}

	// Namespaces come from the columns themselves when creating a schema
	// standalone (the wizard deploy path supplies them from browsed nodes).
	set tDefaultNS = pBody.%Get("defaultNamespace")
	if tDefaultNS = "" {
		set tDefaultNS = ..FindDefaultNamespace(tColumns)
	} else {
		set tDefaultNS = +tDefaultNS
	}
	kill tColNS
	for i=0:1:tColumns.%Size()-1 {
		set tNS = tColumns.%Get(i).%Get("nodeNs")
		set:tNS'="" tColNS(i) = +tNS
	}

	// JSON false arrives as 0; absent means the default, true.
	set tIncludeServerTS = pBody.%Get("includeServerTimestamp")
	set tIncludeServerTS = $Case($ZConvert(tIncludeServerTS, "L"), "":1, "false":0, "0":0, :1)

	set tSC = ..GenerateSchemaClass(tClassName, tDataSourceName, tColumns, tDefaultNS, .tColNS, .tSerialClasses, tIncludeServerTS)
	Quit:$$$ISERR(tSC)

	set pResult.created = 1
	set pResult.schemaClass = tClassName
	set pResult.dataSourceName = tDataSourceName
	set pResult.tableName = ..TableName(tClassName)
	set pResult.columnCount = tColumns.%Size()
	set pResult.serialClasses = $Get(tSerialClasses, 0)
	do pResult.%Set("includeServerTimestamp", tIncludeServerTS, "boolean")

} Catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

#dim tSC As %Status = $$$OK
set pResult = []
Try {
	set tSC = ..MapSchemaUsage(.tUsage)
	Quit:$$$ISERR(tSC)

	set tRS = ##class(%ResultSet).%New("%Dictionary.ClassDefinition:SubclassOf")
	set tSC = tRS.Execute("OPCUA.DataSource.DeviceSchema")
	Quit:$$$ISERR(tSC)

	while tRS.Next() {
		set tClass = tRS.Data("Name")
		continue:tClass="OPCUA.DataSource.DeviceSchema"
		// Skip abstract classes — they cannot back a pipeline.
		continue:$$$comClassKeyGet(tClass,$$$cCLASSabstract)

		// One unreadable schema must not hide the rest: it is listed with
		// its columnsError.
		set tItem = ..DescribeSchema(tClass, 0)
		set tItem.usedBy = ..UsageArray(.tUsage, tClass)
		do pResult.%Push(tItem)
	}
} Catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

#dim tSC As %Status = $$$OK
set pResult = {}
Try {
	set tSC = ..RequireSchema(pBody, .tClassName)
	Quit:$$$ISERR(tSC)

	set tSC = ..MapSchemaUsage(.tUsage)
	Quit:$$$ISERR(tSC)

	set pResult = ..DescribeSchema(tClassName, 1, .tSC)
	if $$$ISERR(tSC) {
		set tSC = ##class(OPCUA.REST.Error).Make(500, "Cannot read the columns of schema '"_tClassName_"'", tSC)
		Quit
	}
	set pResult.usedBy = ..UsageArray(.tUsage, tClassName)
} Catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

#dim tSC As %Status = $$$OK
set pResult = {}
set pResult.deleted = 0
Try {
	set tSC = ..RequireSchema(pBody, .tClassName)
	Quit:$$$ISERR(tSC)

	set tSC = ..MapSchemaUsage(.tUsage)
	Quit:$$$ISERR(tSC)

	// Check if schema is in use in any production
	set tUsageList = ""
	set tProdClass = ""
	for {
		set tProdClass = $Order(tUsage(tClassName, tProdClass))
		quit:tProdClass=""

		set tItemName = ""
		for {
			set tItemName = $Order(tUsage(tClassName, tProdClass, tItemName))
			quit:tItemName=""

			set tEntry = tItemName_" ("_tProdClass_")"
			set tUsageList = tUsageList_$Select(tUsageList="":"", 1:", ")_tEntry
		}
	}

	if tUsageList '= "" {
		set tSC = ##class(OPCUA.REST.Error).Conflict("Schema '"_tClassName_"' is still used by: "_tUsageList)
		Quit
	}

	// Remove the rows first: deleting the class leaves its data global, whose
	// name comes from the class name, so a new schema with the same name would
	// inherit them under a different column layout. %KillExtent, not the "e"
	// delete flag: that deletes row by row, and refuses if any row won't open.
	set tSC = $classmethod(tClassName, "%KillExtent")
	Quit:$$$ISERR(tSC)

	set tSC = ##class(OPCUA.REST.PipelineService).DeleteSerialSubclasses(tClassName)
	Quit:$$$ISERR(tSC)
	set tSC = $System.OBJ.Delete(tClassName, "-d")
	Quit:$$$ISERR(tSC)
	kill ^OPCUA.DataSource(tClassName)

	set pResult.deleted = 1
	set pResult.schemaClass = tClassName
} Catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

#dim tSC As %Status = $$$OK
#dim tClient As OPCUA.Client
set pResult = {}
Try {
	set tSC = ..RequireSchema(pBody, .tClassName)
	Quit:$$$ISERR(tSC)

	set tSC = ..ExtractDeviceSetting(pBody, .tSetting)
	Quit:$$$ISERR(tSC)

	set tSC = ##class(OPCUA.DataSource.Resolver).ParseDeviceNodePaths(tSetting, .tDevices, .tParseErrors)
	if $$$ISERR(tSC) {
		// Surface the per-line reasons, which are far more useful than the summary.
		set tMsg = ##class(OPCUA.REST.Error).Text(tSC)
		for i=1:1:$LL(tParseErrors) { set tMsg = tMsg_"; "_$LI(tParseErrors, i) }
		set tSC = $$$ERROR($$$GeneralError, tMsg)
		Quit
	}

	set tSC = ##class(OPCUA.REST.ClientManager).ExtractConnectionParams(pBody, .tURL, .tSecMode, .tUser, .tPass, .tCert, .tKey, .tTrust, .tCrl, .tClientURI)
	Quit:$$$ISERR(tSC)
	set tSC = ##class(OPCUA.REST.ClientManager).Connect(.tClient, tURL, tSecMode, tUser, tPass, tCert, tKey, tTrust, tCrl, tClientURI)
	Quit:$$$ISERR(tSC)

	set tSC = ##class(OPCUA.DataSource.Resolver).ResolveSpecification(tClient, tClassName, tDevices, .tSpec, .tMasks, .tDiag, .tBrowseOK)
	Quit:$$$ISERR(tSC)

	// Column names in the same order the masks use.
	set tSC = ##class(OPCUA.DataSource.Resolver).GetSchemaColumns(tClassName, .tColumns, .tFolders)
	Quit:$$$ISERR(tSC)

	set pResult.schemaClass = tClassName
	set pResult.columnCount = tColumns
	set tDevArray = []
	set tAllResolved = 1

	for iDev=1:1:$LL(tDevices) {
		set tDev = $LI(tDevices, iDev)
		set tMask = $LI(tMasks, iDev)

		set tEntry = {}
		set tEntry.label = $LI(tDev, 4)
		set tEntry.nodeNs = $LI(tDev, 1)
		set tEntry.nodeId = $LI(tDev, 2)

		set tMatched = [], tMissing = []
		for iCol=1:1:tColumns {
			set tCol = tColumns(iCol)
			set tFolderName = $LI(tCol, 5)
			set tName = $Select(tFolderName="":$LI(tCol, 3), 1:tFolderName_"/"_$LI(tCol, 3))
			if +$LI(tMask, iCol) {
				do tMatched.%Push(tName)
			} else {
				do tMissing.%Push(tName)
				set tAllResolved = 0
			}
		}
		set tEntry.matched = tMatched
		set tEntry.missing = tMissing
		set tEntry.matchedCount = tMatched.%Size()
		set tEntry.missingCount = tMissing.%Size()
		set tEntry.complete = (tMissing.%Size() = 0)

		// Zero matches means different things depending on whether the server
		// answered, and only one of them is a binding worth making.
		set tBrowsed = +$LI(tBrowseOK, iDev)
		set tUsable = (tBrowsed && (tMatched.%Size() > 0))
		set tEntry.browsed = tBrowsed
		set tEntry.usable = tUsable
		if 'tUsable {
			set tEntry.unusableReason = $Select('tBrowsed:"could not be browsed — the device is unreachable, or this NodeId does not exist on the server", 1:"browsed successfully but matched none of the schema's columns — every row would be entirely NULL")
		}
		do tDevArray.%Push(tEntry)
	}

	set pResult.devices = tDevArray
	set pResult.allResolved = tAllResolved

	// Raw diagnostics, so a caller can show the resolver's own wording.
	set tDiagArray = []
	for i=1:1:$LL(tDiag) {
		set tD = $LI(tDiag, i)
		set tObj = {}
		set tObj.device = $LI(tD, 1)
		set tObj.column = $LI(tD, 2)
		set tObj.reason = $LI(tD, 3)
		do tDiagArray.%Push(tObj)
	}
	set pResult.diagnostics = tDiagArray

} Catch (e) {
	set tSC = e.AsStatus()
}
do ##class(OPCUA.REST.ClientManager).Disconnect($Get(tClient))
Quit tSC

#dim tSC As %Status = $$$OK
Try {
	// Copy the caller's body, overriding only how the schema is identified, so
	// url/securityMode/certificates still reach the browse.
	set tReq = {}.%FromJSON(pBody.%ToJSON())
	do tReq.%Set("className", pSchemaClass)
	do tReq.%Set("name", "")

	set tSC = ..Validate(tReq, .tVal)
	Quit:$$$ISERR(tSC)

	set tDevices = tVal.%Get("devices")
	if '$IsObject($Get(tDevices)) Quit

	set tMsg = ""
	set tBad = 0
	for i=0:1:tDevices.%Size()-1 {
		set tD = tDevices.%Get(i)
		continue:+tD.%Get("usable")
		set tBad = tBad + 1
		set tMsg = tMsg_$Select(tMsg="":"", 1:"; ")_"'"_tD.%Get("label")_"' "_tD.%Get("unusableReason")
	}

	if tBad > 0 {
		set tSC = $$$ERROR($$$GeneralError, "Cannot bind "_tBad_" device(s) — "_tMsg_". Remove the device, or point it at the node that actually holds the schema's values.")
	}
} Catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

#dim tSC As %Status = $$$OK
kill pSerialClasses
set pSerialClasses = 0
kill tCreatedClasses
Try {
	// Separate flat columns from nested ones and build the folder tree.
	kill tFolderColumns
	set tHasNesting = 0
	for i=0:1:pColumns.%Size()-1 {
		set tCol = pColumns.%Get(i)
		set tRelPath = tCol.%Get("relativePath")
		if '$IsObject($Get(tRelPath)) || (tRelPath.%Size() <= 1) continue
		set tFolderName = tRelPath.%Get(0)
		set tHasNesting = 1
		if '$Data(tFolderColumns(tFolderName)) {
			set tFolderColumns(tFolderName) = ##class(%DynamicArray).%New()
		}
		set tSubCol = ##class(%DynamicObject).%New()
		set tSubCol.displayName = tCol.%Get("displayName")
		set tSubCol.inferredType = tCol.%Get("inferredType")
		set tSubCol.leafName = tRelPath.%Get(tRelPath.%Size()-1)
		do tFolderColumns(tFolderName).%Push(tSubCol)
	}

	// Serial classes must exist before the main class references them.
	if tHasNesting {
		// Throw, not Quit: the Catch below removes the serial classes this
		// call already created. A Quit would leave the Try without it.
		set tSC = ..GenerateSerialClasses(pClassName, pDefaultNS, .tFolderColumns, .pSerialClasses, pIncludeServerTS, .tCreatedClasses)
		$$$ThrowOnError(tSC)
	}

	set tClassDef = ##class(%Dictionary.ClassDefinition).%New(pClassName)
	set tClassDef.Description = "Auto-generated OPC UA device schema with per-measurement value, quality and "_$Select(pIncludeServerTS:"timestamps.", 1:"source timestamp (no server timestamp).")
	// Extend DeviceSchema (not Definition) so the class is discoverable by the
	// DataSourceClass dropdown, which filters on this superclass.
	set tClassDef.Super = "%Persistent,OPCUA.DataSource.DeviceSchema"

	do ..AddParameter(tClassDef, "OPCUADATASOURCE", pDataSourceName)
	do ..AddParameter(tClassDef, "OPCUDEFAULTANAMESPACE", pDefaultNS)
	do ..AddParameter(tClassDef, "OPCUAPIPELINEVERSION", 2)

	// Device identity is row-level; timestamps and status belong to each measurement.
	set tProp = ##class(%Dictionary.PropertyDefinition).%New()
	set tProp.Name = "NodePath"
	set tProp.Type = "%String"
	do tProp.Parameters.SetAt(500, "MAXLEN")
	do tClassDef.Properties.Insert(tProp)

	// Test hook: inject a bad property type to force compile failure
	if $Get(^||OPCUA.Tests("badProp")) {
		set tProp = ##class(%Dictionary.PropertyDefinition).%New()
		set tProp.Name = "BadProperty"
		set tProp.Type = "ThisClassDoesNotExist"
		do tClassDef.Properties.Insert(tProp)
	}

	// Column properties
	kill tEmittedFolders, tUsedNames
	for i=0:1:pColumns.%Size()-1 {
		set tCol = pColumns.%Get(i)
		set tDisplayName = tCol.%Get("displayName")
		set tInferredType = tCol.%Get("inferredType")
		set tRelPath = tCol.%Get("relativePath")

		set tIsNested = $IsObject($Get(tRelPath)) && (tRelPath.%Size() > 1)
		if tIsNested {
			// One property per folder, emitted once, typed as the serial class.
			set tFolderName = tRelPath.%Get(0)
			if $Data(tEmittedFolders(tFolderName)) continue
			set tEmittedFolders(tFolderName) = 1

			set tSerialClassName = ..SerialClassName(pClassName, tFolderName)
			set tPropName = ##class(OPCUA.DataSource.Generator).SanitizePropertyName(tFolderName, .tUsedNames)
			set tProp = ##class(%Dictionary.PropertyDefinition).%New()
			set tProp.Name = tPropName
			set tProp.Type = tSerialClassName
			do tProp.Parameters.SetAt(tFolderName, "OPCUANODENAME")
			do tClassDef.Properties.Insert(tProp)
		} else {
			set tType = ..MapToDataValueType(tInferredType, pIncludeServerTS)
			set tChildNS = $Get(pColNamespaces(i), pDefaultNS)
			set tLeafName = tDisplayName
			if $IsObject($Get(tRelPath)) && (tRelPath.%Size() = 1) {
				set tLeafName = tRelPath.%Get(0)
			}
			set tPropName = ##class(OPCUA.DataSource.Generator).SanitizePropertyName(tLeafName, .tUsedNames)
			set tProp = ##class(%Dictionary.PropertyDefinition).%New()
			set tProp.Name = tPropName
			set tProp.Type = tType
			do tProp.Parameters.SetAt(tLeafName, "OPCUANODENAME")
			if tChildNS '= pDefaultNS {
				do tProp.Parameters.SetAt(tChildNS, "OPCUANAMESPACE")
			}
			do tClassDef.Properties.Insert(tProp)
		}
	}

	set tSC = tClassDef.%Save()
	$$$ThrowOnError(tSC)
	set tCreatedClasses($Increment(tCreatedClasses)) = pClassName
	set tSC = $System.OBJ.Compile(pClassName, "ck-d")
	$$$ThrowOnError(tSC)

} Catch (e) {
	set tSC = e.AsStatus()
	// Clean up any classes created by this call
	set i = ""
	for {
		set i = $Order(tCreatedClasses(i))
		quit:i=""
		set tClassName = tCreatedClasses(i)
		if ##class(%Dictionary.ClassDefinition).%ExistsId(tClassName) {
			// Test seam: force a delete failure for a specific class
			if $Get(^||OPCUA.Tests("deleteFailClass")) = tClassName {
				set tDelSC = $$$ERROR($$$GeneralError, "Test-forced delete failure")
			} else {
				set tDelSC = $System.OBJ.Delete(tClassName, "-d")
			}
			if $$$ISERR(tDelSC) {
				set tSC = $$$ADDSC(tSC, $$$ERROR($$$GeneralError, "Failed to delete class '"_tClassName_"' during rollback"))
			}
		}
	}
}
Quit tSC

#dim tSC As %Status = $$$OK
Try {
	set pSerialClasses = 0

	// Check all target serial class names upfront
	set tFolderName = ""
	for {
		set tFolderName = $Order(pFolderColumns(tFolderName))
		if tFolderName = "" Quit

		set tSerialClassName = ..SerialClassName(pMainClassName, tFolderName)

		// Sanitising is lossy, so two folder names can collapse onto one class
		// name ("A_B" and "AB"). Silently generating the second over the first
		// would drop its columns, so refuse instead.
		if $Data(tTakenNames(tSerialClassName)) {
			set tSC = $$$ERROR($$$GeneralError, "Folders '"_tTakenNames(tSerialClassName)_"' and '"_tFolderName_"' both map to class '"_tSerialClassName_"'. Rename one, or select their columns from a single folder.")
			Quit
		}
		set tTakenNames(tSerialClassName) = tFolderName

		// Check if class already exists
		if ##class(%Dictionary.ClassDefinition).%ExistsId(tSerialClassName) {
			set tSC = ##class(OPCUA.REST.Error).Conflict("Class '"_tSerialClassName_"' already exists. Choose different folder names or a different schema name.")
			Quit
		}
	}
	Quit:$$$ISERR(tSC)

	// Now create and compile the serial classes
	set tFolderName = ""
	for {
		set tFolderName = $Order(pFolderColumns(tFolderName))
		if tFolderName = "" Quit

		set tSerialClassName = ..SerialClassName(pMainClassName, tFolderName)
		set tColumns = pFolderColumns(tFolderName)

		set tClassDef = ##class(%Dictionary.ClassDefinition).%New(tSerialClassName)
		set tClassDef.Description = "Auto-generated serial object for nested OPC UA folder: "_tFolderName
		set tClassDef.Super = "%SerialObject"
		set tClassDef.PropertyClass = "OPCUA.DataSource.PropertyClass"

		// Test hook: inject a bad property type into serial class number N
		// (^||OPCUA.Tests("badProp", "serial") = N) to force its compile to fail.
		if $Get(^||OPCUA.Tests("badProp", "serial")) = (pSerialClasses + 1) {
			set tProp = ##class(%Dictionary.PropertyDefinition).%New()
			set tProp.Name = "BadProperty"
			set tProp.Type = "ThisClassDoesNotExist"
			do tClassDef.Properties.Insert(tProp)
		}

		kill tUsedNames
		for i=0:1:tColumns.%Size()-1 {
			set tSubCol = tColumns.%Get(i)
			set tLeafName = tSubCol.%Get("leafName")
			set tType = ..MapToDataValueType(tSubCol.%Get("inferredType"), pIncludeServerTS)
			set tPropName = ##class(OPCUA.DataSource.Generator).SanitizePropertyName(tLeafName, .tUsedNames)

			set tProp = ##class(%Dictionary.PropertyDefinition).%New()
			set tProp.Name = tPropName
			set tProp.Type = tType
			do tProp.Parameters.SetAt(tLeafName, "OPCUANODENAME")
			do tClassDef.Properties.Insert(tProp)
		}

		set tSC = tClassDef.%Save()
		$$$ThrowOnError(tSC)
		set pCreatedClasses($Increment(pCreatedClasses)) = tSerialClassName
		set tSC = $System.OBJ.Compile(tSerialClassName, "ck-d")
		$$$ThrowOnError(tSC)

		set pSerialClasses = pSerialClasses + 1
		set pSerialClasses(pSerialClasses) = $LB(tSerialClassName, "")
	}

} Catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

if $Extract(pInferredType, 1, 12) = "OPCUA.Types." {
	if ##class(%Dictionary.CompiledClass).%ExistsId(pInferredType) {
		if (pInferredType '= "OPCUA.Types.AbstractDataValue") && $classmethod(pInferredType, "%Extends", "OPCUA.Types.AbstractDataValue") {
			Quit pInferredType
		}
	}
}
if pInferredType = "%Double" Quit "OPCUA.Types.DoubleDataValue"
if pInferredType = "%Numeric" Quit "OPCUA.Types.DoubleDataValue"
if pInferredType = "%Float" Quit "OPCUA.Types.FloatDataValue"
if pInferredType = "%Integer" Quit "OPCUA.Types.IntegerDataValue"
if pInferredType = "%Boolean" Quit "OPCUA.Types.BooleanDataValue"
if pInferredType = "%TimeStamp" Quit "OPCUA.Types.TimeStampDataValue"
Quit "OPCUA.Types.StringDataValue"

for i=0:1:pNodes.%Size()-1 {
	set tNS = +pNodes.%Get(i).%Get("nodeNs")
	set tNSCount(tNS) = $Get(tNSCount(tNS), 0) + 1
}
set tDefaultNS = 0
set tMaxCount = 0
set tNS = ""
for {
	set tNS = $Order(tNSCount(tNS))
	if tNS = "" Quit
	if tNSCount(tNS) > tMaxCount {
		set tMaxCount = tNSCount(tNS)
		set tDefaultNS = tNS
	}
}
Quit tDefaultNS

set pClassName = pBody.%Get("className")
if pClassName = "" {
	set tName = pBody.%Get("name")
	if tName = "" {
		Quit $$$ERROR($$$GeneralError, "Missing schema name (supply 'className', or 'name' with optional 'packagePath')")
	}
	if tName [ "." {
		// A dotted name is already fully qualified.
		set pClassName = tName
	} else {
		set tPackage = pBody.%Get("packagePath")
		if tPackage = "" set tPackage = ..#DefaultPackage
		set pClassName = tPackage_"."_tName
	}
}
if '##class(%Dictionary.Classname).IsValid(pClassName) {
	Quit ##class(OPCUA.REST.Error).BadRequest("'"_pClassName_"' is not a valid schema name. Use letters and digits only, starting with a letter (no spaces, hyphens or underscores), with dots only between package parts.")
}
Quit $$$OK

set tSC = ..ResolveClassName(pBody, .pClassName)
Quit:$$$ISERR(tSC) tSC

if '##class(%Dictionary.ClassDefinition).%ExistsId(pClassName) {
	Quit ##class(OPCUA.REST.Error).NotFound("Schema '"_pClassName_"' does not exist")
}
if '..IsSchema(pClassName) {
	Quit $$$ERROR($$$GeneralError, "Class '"_pClassName_"' is not an OPCUA.DataSource.DeviceSchema subclass")
}
Quit $$$OK

set tIs = 0
Try {
	if pClassName '= "OPCUA.DataSource.DeviceSchema" {
		set tIs = $classmethod(pClassName, "%Extends", "OPCUA.DataSource.DeviceSchema")
	}
} Catch (e) {
	set tIs = 0
}
Quit tIs

set pSC = $$$OK
set tItem = {}
set tItem.schemaClass = pClassName
set tItem.name = $Piece(pClassName, ".", *)
set tItem.packagePath = $Piece(pClassName, ".", 1, *-1)
set tItem.tableName = ..TableName(pClassName)

Try {
	set tCD = ##class(%Dictionary.CompiledClass).%OpenId(pClassName)
	if $IsObject(tCD) {
		for i=1:1:tCD.Parameters.Count() {
			set tP = tCD.Parameters.GetAt(i)
			if tP.Name = "OPCUADATASOURCE" set tItem.dataSourceName = tP.Default
			if tP.Name = "OPCUDEFAULTANAMESPACE" set tItem.defaultNamespace = tP.Default
		}
	}

	set tSC = ##class(OPCUA.DataSource.Resolver).GetSchemaColumns(pClassName, .tColumns, .tFolders)
	if $$$ISOK(tSC) {
		set tItem.columnCount = tColumns
		if pWithColumns {
			set tArr = []
			for i=1:1:tColumns {
				set tCol = tColumns(i)
				set tObj = {}
				set tObj.nodeName = $LI(tCol, 3)
				set tObj.namespace = $LI(tCol, 2)
				set tObj.attributeId = $LI(tCol, 4)
				set tObj.folder = $LI(tCol, 5)
				set tObj.propertyPath = $LI(tCol, 1)
				do tArr.%Push(tObj)
			}
			set tItem.columns = tArr
		}
	} else {
		set pSC = tSC
	}
} Catch (e) {
	set pSC = e.AsStatus()
}
if $$$ISERR(pSC) {
	set tItem.columnCount = 0
	set tItem.columnsError = ##class(OPCUA.REST.Error).Text(pSC)
}

Quit tItem

#dim tSC As %Status = $$$OK
kill pUsage
Try {
	// Test seam: force a failure to test error handling
	if $Get(^||OPCUA.Tests("failUsage")) {
		set tSC = ##class(OPCUA.REST.Error).Make(500, "Forced usage check failure")
		Quit
	}

	// Iterate every production in the namespace. Embedded SQL, which checks no
	// SQL privilege, so an account with only the installer's OPCUA_API role can
	// run it (dynamic SQL gave it SQLCODE -99). A failed query must still stop
	// the caller: read as "no productions", schema delete would skip its
	// in-use check.
	&sql(DECLARE cUsageProd CURSOR FOR SELECT ID INTO :tProdClass FROM Ens_Config.Production)
	&sql(OPEN cUsageProd)
	if SQLCODE < 0 {
		set tSC = ##class(OPCUA.REST.Error).Make(500, "Failed to query Ens_Config.Production", $$$ERROR($$$SQLError, SQLCODE, $Get(%msg)))
		Quit
	}
	for {
		&sql(FETCH cUsageProd)
		if SQLCODE = 100 Quit
		if SQLCODE < 0 {
			set tSC = ##class(OPCUA.REST.Error).Make(500, "Failed to query Ens_Config.Production", $$$ERROR($$$SQLError, SQLCODE, $Get(%msg)))
			Quit
		}
		set tProd = ##class(Ens.Config.Production).%OpenId(tProdClass)
		if '$IsObject(tProd) {
			set tSC = ##class(OPCUA.REST.Error).Make(500, "Failed to open production '"_tProdClass_"'")
			Quit
		}

		for i=1:1:tProd.Items.Count() {
			set tItem = tProd.Items.GetAt(i)
			for j=1:1:tItem.Settings.Count() {
				set tS = tItem.Settings.GetAt(j)
				continue:tS.Name'="DataSourceClass"
				continue:tS.Value=""
				set pUsage(tS.Value, tProdClass, tItem.Name) = ""
			}
		}
	}
	&sql(CLOSE cUsageProd)
} Catch (e) {
	set tSC = e.AsStatus()
	&sql(CLOSE cUsageProd)
}
Quit tSC

set pSetting = ""
set tDevices = pBody.%Get("devices")
if tDevices = "" set tDevices = pBody.%Get("deviceNodePaths")

if $IsObject($Get(tDevices)) {
	// JSON array: strings, or objects with nodePath/path (+ optional label)
	for i=0:1:tDevices.%Size()-1 {
		set tD = tDevices.%Get(i)
		if $IsObject($Get(tD)) {
			set tPath = tD.%Get("nodePath")
			if tPath = "" set tPath = tD.%Get("path")
			set tLabel = tD.%Get("label")
			set:tLabel'="" tPath = tPath_"|"_tLabel
		} else {
			set tPath = tD
		}
		continue:tPath=""
		set pSetting = pSetting_$Select(pSetting="":"", 1:$Char(10))_tPath
	}
} else {
	set pSetting = tDevices
}

if pSetting = "" {
	Quit $$$ERROR($$$GeneralError, "No devices supplied — provide 'devices' as newline-separated nodepaths or an array")
}
Quit $$$OK

#dim tSC As %Status = $$$OK
try {
	set tMasks = ..Adapter.RowSourceMasks
	set tPaths = ..Adapter.RowSourcePaths
	set tSC = ..RowWriter.CheckInput(.pInputAsList, tMasks)
	Quit:$$$ISERR(tSC)
	set tResultIdx = 1
	for iRS=1:1:$LL(tMasks) {
		set tSC = ..RowWriter.BuildRow(.pInputAsList, $LI(tMasks, iRS), $LI(tPaths, iRS), .tResultIdx, .tRowData, .tQualityChanges)
		Quit:$$$ISERR(tSC)
		do ..RowWriter.LogQualityChanges($LI(tPaths, iRS), tQualityChanges)
		set tSC = $CLASSMETHOD(..Adapter.DataSourceClass, "SaveSourcedData", .tRowData)
		if $$$ISERR(tSC) {
			$$$LOGERROR("Failed to save device "_iRS_" ("_$LI(tPaths, iRS)_"): "_$System.Status.GetErrorText(tSC))
			set tSC = $$$OK
		}
	}
} catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

#dim tSC as %Status = $$$OK

try {

	// Get the spec
	set tSpecification = ##class(OPCUA.DataSource.Projection).GetOPCUAConfigSpec(..Adapter.DataSourceClass)

	$$$LOGINFO("Configuring OPCUA polling adapter")
	set tSC = ..Adapter.Configure(.tSpecification)

} catch (e) {
	set tSC = e.AsStatus()
}

Quit tSC

 	#dim tSC as %Status = $$$OK

	try {

		set $LI(pInputAsList,1) = ""

		set tSC = $CLASSMETHOD(..Adapter.DataSourceClass,"SaveSourcedData",.pInputAsList)

	} catch (e) {
		set tSC = e.AsStatus()
	}

	return tSC

#dim tSC As %Status = $$$OK
try {
	set tMasks = ..Adapter.RowSourceMasks
	set tPaths = ..Adapter.RowSourcePaths
	set tSC = ..RowWriter.CheckInput(.pInputAsList, tMasks)
	Quit:$$$ISERR(tSC)
	set tResultIdx = 1
	for iRS=1:1:$LL(tMasks) {
		set tSC = ..RowWriter.BuildRow(.pInputAsList, $LI(tMasks, iRS), $LI(tPaths, iRS), .tResultIdx, .tRowData, .tQualityChanges)
		Quit:$$$ISERR(tSC)
		do ..RowWriter.LogQualityChanges($LI(tPaths, iRS), tQualityChanges)
		set tSC = $CLASSMETHOD(..Adapter.DataSourceClass, "SaveSourcedData", .tRowData)
		if $$$ISERR(tSC) {
			$$$LOGERROR("Failed to save device "_iRS_" ("_$LI(tPaths, iRS)_"): "_$System.Status.GetErrorText(tSC))
			set tSC = $$$OK
		}
	}
} catch (e) {
	set tSC = e.AsStatus()
}
Quit tSC

#dim tSC as %Status = $$$OK

try {

	// Get the spec
	set tSpecification = ##class(OPCUA.DataSource.Projection).GetOPCUAConfigSpec(..Adapter.DataSourceClass)

	$$$LOGINFO("Configuring OPCUA subscription adapter")
	set tSC = ..Adapter.Configure(.tSpecification)

} catch (e) {
	set tSC = e.AsStatus()
}

Quit tSC

 	#dim tSC as %Status = $$$OK

	try {

		set $LI(pInputAsList,1) = ""

		set tSC = $CLASSMETHOD(..Adapter.DataSourceClass,"SaveSourcedData",.pInputAsList)

	} catch (e) {
		set tSC = e.AsStatus()
	}

	return tSC

    try {

        #; See ##class(OPCUA.Class).GetStatusCodeName()

        set tOpcuaStatusCode = 0 // Status = "Good"

        If '$Data(%ZUtilsIrisOpcuaLibraryId) {
            Set tSC = $$$ERROR($$$GeneralError, "IrisOPCUA library is not loaded")
            Quit
        }

		//set tRetval=$ZF(-6,$$$IrisOPCUALibrary,$$$zfGetStatusCodeNameB,"",$LB(tOpcuaStatusCode))
		set tRetval=$ZF(-5,%ZUtilsIrisOpcuaLibraryId,$$$zfGetStatusCodeNameB,"",$LB(tOpcuaStatusCode))

        If $List(tRetval,1)=0 return $$$OK // Library is already initialized

    } catch (e) {
        $$$TRACE("IrisOPCUA may not be loaded")
    }

    #dim tSC as %Status = $$$OK
    #dim tPathname as %String = ""

    try {

        //set tPathname = ^OPCUA.Library.Pathname
        set tSC = ##class(OPCUA.Utils).GetLibPathname(.tPathname)
		$$$ThrowOnError(tSC)

        $$$TRACE("Attempting to load IrisOPCUA with pathname '"_tPathname_"'")

        //do $ZF(-4,5,$$$IrisOPCUALibrary,tPathname)
        set %ZUtilsIrisOpcuaLibraryId = $ZF(-4,1,tPathname)

    } catch (e) {
        set tSC = e.AsStatus()
        $$$LOGERROR("Error thrown during IrisOPCUA handle assignment : "_$SYSTEM.Status.GetErrorText(tSC))
    }

    // Keep the first error - don't reset tSC to $$$OK after a failure
    If $$$ISERR(tSC) Quit tSC

    try {

        If '$Data(%ZUtilsIrisOpcuaLibraryId) {
            Set tSC = $$$ERROR($$$GeneralError, "IrisOPCUA library is not loaded: "_tPathname)
            Quit
        }

		//set tRetval=$ZF(-6,$$$IrisOPCUALibrary,$$$zfGetStatusCodeNameB,"",$LB(0))
		set tRetval=$ZF(-5,%ZUtilsIrisOpcuaLibraryId,$$$zfGetStatusCodeNameB,"",$LB(0))

        If $List(tRetval,1)'=0 Set tSC=##class(OPCUA.Client).DecodeError(tRetval)

        if $$$ISERR(tSC) {
            $$$LOGERROR("Unable to load IrisOPCUA : Error returned : "_$SYSTEM.Status.GetErrorText(tSC))
        } Else {

            set tSC = ##class(OPCUA.Utils).GetVersion(.tRetval) // Reusing tRetval
            Quit:$$$ISERR(tSC)

            set tVersion = "v"_$LI(tRetval,2)
            $$$LOGINFO("IrisOPCUA loaded successfully : "_tVersion)
        }

    } catch (e) {
        set tSC = e.AsStatus()
        $$$LOGERROR("Unable to load IrisOPCUA : Error thrown : "_$SYSTEM.Status.GetErrorText(tSC))
    }

    Quit tSC

#dim tSC as %Status = $$$OK

try {    

    set ^OPCUA.Library.Pathname = pPathname

} catch (e) {
    set tSC = e.AsStatus()
}

Quit tSC

#dim tSC as %Status = $$$OK

try {

    // Test seam: allow tests to override the library path
    if ($GET(^||OPCUA.LibPathOverride) '= "") set pPathname = ^||OPCUA.LibPathOverride Quit

    if ($GET(^OPCUA.Library.Pathname) '= "") set pPathname = ^OPCUA.Library.Pathname Quit

    set tPathname = $System.Util.BinaryDirectory()_"IrisOPCUA.dll"
    if ##class(%File).Exists(tPathname) set pPathname = tPathname Quit

    set tPathname = $System.Util.BinaryDirectory()_"irisopcua.so"
    if ##class(%File).Exists(tPathname) set pPathname = tPathname Quit

    set pPathname = ""
    set tSC = $System.Status.Error(5012, "IrisOPCUA.dll/.so")

} catch (e) {
    set pPathname = ""
    set tSC = e.AsStatus()
}

Quit tSC

set tRet=""

try {

    if $System.Version.IsUnicode() {

        set tLen=$L(pStr),i=1
        while i <= tLen {
            set c = $E(pStr,i,i)
            if c = "\" {
                if i + 1 > tLen Quit // ERROR
                set c = $E(pStr,i+1,i+1)
                if c = "\" {
                    set tRet=tRet_"\",i=i+2
                } elseif c = "u" {
                    if i + 5 > tLen Quit // ERROR
                    set tRet=tRet_$C($SYSTEM.Util.HexToDecimal($E(pStr,i+2,i+5))),i=i+6
                } else { 
                    Quit // ERROR
                }
            } else { 
                set tRet=tRet_c,i=i+1
            }
        }

    } else {

        // Ignored: a library that is not loaded fails the $ZF below, and this
        // decoder returns fragments rather than errors by design.
        do ##class(OPCUA.Utils).Initialize()
        set tRetval=$ZF(-5,%ZUtilsIrisOpcuaLibraryId,$$$zfGetUStr,"",$LB(pStr,1))

        #; Errors are not returned, fragments instead.
        #; Ignore any error. Return the result.
        set tRet = $LI(tRetval,2)

    }


} catch (e) {
    // Ignore errors. Return the result.
}

return tRet

if $FIND(ErrStr1,"0x800A0000") {
    return $FIND(ErrStr2,"0x80AD0000") || $FIND(ErrStr2,"0x80AE0000")
} elseif $FIND(ErrStr1,"0x80AD0000") {
    return $FIND(ErrStr2,"0x800A0000") || $FIND(ErrStr2,"0x80AE0000")
} elseif $FIND(ErrStr1,"0x80AE0000") {
    return $FIND(ErrStr2,"0x800A0000") || $FIND(ErrStr2,"0x80AD0000")
} else {
    return 0
}
#; if $FIND(ErrStr1,"0x800A0000") {
#;     return $FIND(ErrStr2,"0x80AD0000")
#; } elseif $FIND(ErrStr1,"0x80AD0000") {
#;     return $FIND(ErrStr2,"0x800A0000")
#; } else {
#;     return 0
#; }

    #dim tSC as %Status = $$$OK

    try {

		set tRetval=$ZF(-5,%ZUtilsIrisOpcuaLibraryId,$$$zfVersion,"")

        #; Test for error condition
        If $List(tRetval,1)'=0 Set tSC=##class(OPCUA.Client).DecodeError(tRetval) Quit

        #; Set output variables
        Set pOut = tRetval

	} Catch (e) {
		Set tSC=e.AsStatus()
	}

	Quit tSC

set tRS = ##class(%SQL.Statement).%ExecDirect(, pSQL, pArgs...)
if tRS.%SQLCODE = -99 {
	$$$ThrowStatus(##class(OPCUA.REST.Error).Forbidden("Your IRIS account ("_$Username_") lacks an SQL privilege this request needs: "_tRS.%Message_". Ask an administrator to grant it, or use an account with more privileges."))
}
if tRS.%SQLCODE < 0 $$$ThrowStatus($$$ERROR($$$SQLError, tRS.%SQLCODE, tRS.%Message))
Quit tRS
